import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart as RePieChart, Pie, Cell } from 'recharts';
import { Order } from '../types';

interface DashboardProps {
  orders: Order[];
}

const COLORS = ['#ef4444', '#fecaca', '#3b82f6', '#10b981'];

const Dashboard: React.FC<DashboardProps> = ({ orders }) => {
  const paidOrders = orders.filter(o => o.status === 'paid');
  const totalSales = paidOrders.reduce((sum, o) => sum + o.total, 0);
  const totalInvoices = paidOrders.length;
  const upiSales = paidOrders.filter(o => o.paymentMethod === 'UPI').reduce((sum, o) => sum + o.total, 0);
  const cashSales = paidOrders.filter(o => o.paymentMethod === 'Cash').reduce((sum, o) => sum + o.total, 0);
  const totalDiscount = paidOrders.reduce((sum, o) => sum + o.discount, 0);

  const itemCounts: Record<string, number> = {};
  paidOrders.forEach(o => o.items.forEach(i => {
    itemCounts[i.name] = (itemCounts[i.name] || 0) + i.qty;
  }));

  const barData = Object.entries(itemCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, val]) => ({ name, val }));

  const pieData = [
    { name: 'Dine In', value: totalSales },
    { name: 'Takeaway', value: 0 },
  ];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Dashboard</h2>
        <button className="px-4 py-2 bg-white border border-gray-200 rounded-md text-sm font-medium hover:bg-gray-50">Filter</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        {[
          { label: 'Total Sales', value: `₹${totalSales.toFixed(2)}` },
          { label: 'Total Invoice', value: totalInvoices },
          { label: 'Dine In Sales', value: `₹${totalSales.toFixed(2)}` },
          { label: 'UPI Payment Sales', value: `₹${upiSales.toFixed(2)}` },
          { label: 'Cash Payment Sales', value: `₹${cashSales.toFixed(2)}` },
          { label: 'Card Payment Sales', value: '₹0.00' },
          { label: 'Active Table', value: '0', highlight: true },
          { label: 'Total Given Discount', value: `₹${totalDiscount.toFixed(2)}`, highlight: true },
          { label: 'Live Total No. of Orders', value: '0', highlight: true },
        ].map((card, idx) => (
          <div key={idx} className={`p-5 rounded-lg border border-gray-100 ${card.highlight ? 'bg-blue-600 text-white' : 'bg-white shadow-sm'}`}>
            <p className={`text-xs font-semibold uppercase mb-2 ${card.highlight ? 'text-blue-100' : 'text-gray-500'}`}>{card.label}</p>
            <p className="text-xl font-bold">{card.value}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-lg border border-gray-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6">Most Order Items</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis fontSize={12} tickLine={false} axisLine={false} />
                <Tooltip />
                <Bar dataKey="val" fill="#ef4444" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg border border-gray-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6">Order Type Sale Summary</h3>
          <div className="h-64 flex items-center">
            <ResponsiveContainer width="100%" height="100%">
              <RePieChart>
                <Pie data={pieData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </RePieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Table, MenuItem, Order, OrderItem, PaymentMethod } from '../types';
import { Plus, Minus, X, Check } from 'lucide-react';

interface DineInProps {
  tables: Table[];
  menu: MenuItem[];
  onOrderComplete: (order: Order, tableId: string) => void;
  onTableUpdate: (tableId: string, updates: Partial<Table>) => void;
}

const DineIn: React.FC<DineInProps> = ({ tables, menu, onOrderComplete, onTableUpdate }) => {
  const [rearrangeMode, setRearrangeMode] = useState(false);
  const [selectedTable, setSelectedTable] = useState<Table | null>(null);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [discount, setDiscount] = useState(0);

  const handleTableClick = (table: Table) => {
    if (rearrangeMode) return;
    setSelectedTable(table);
    setCart([]); // In real app, load existing order if occupied
  };

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, qty: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => prev.map(i => i.id === itemId ? { ...i, qty: Math.max(0, i.qty - 1) } : i).filter(i => i.qty > 0));
  };

  const calculateTotal = () => {
    const subtotal = cart.reduce((sum, i) => sum + i.price * i.qty, 0);
    const tax = subtotal * 0.05; // 5% GST
    const total = subtotal + tax - discount;
    return { subtotal, tax, total };
  };

  const handlePlaceOrder = (status: 'pending' | 'billed' | 'paid', payment: PaymentMethod = '-') => {
    if (!selectedTable || cart.length === 0) return;
    const { subtotal, tax, total } = calculateTotal();
    const order: Order = {
      id: `#${Math.floor(Math.random() * 1000)}`,
      tableId: selectedTable.id,
      tableName: selectedTable.name,
      items: cart,
      subtotal,
      tax,
      discount,
      total,
      status: status as any,
      paymentMethod: payment,
      createdAt: Date.now()
    };

    onOrderComplete(order, selectedTable.id);

    const tableStatus = status === 'paid' ? 'vacant' : (status === 'billed' ? 'billed' : 'occupied');
    onTableUpdate(selectedTable.id, { 
      status: tableStatus, 
      orderValue: status === 'paid' ? undefined : total 
    });

    setSelectedTable(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-lg shadow-sm border border-gray-100">
        <div>
          <h2 className="text-xl font-bold">Floor Plan</h2>
          <div className="flex items-center mt-2 space-x-4">
            <div className="flex items-center text-xs"><div className="w-3 h-3 bg-green-500 rounded-full mr-2"></div> Vacant</div>
            <div className="flex items-center text-xs"><div className="w-3 h-3 bg-red-500 rounded-full mr-2"></div> Occupied</div>
            <div className="flex items-center text-xs"><div className="w-3 h-3 bg-yellow-500 rounded-full mr-2"></div> Billed</div>
          </div>
        </div>
        <div className="flex items-center">
          <span className="mr-3 text-sm font-medium">Rearrange Mode</span>
          <button 
            onClick={() => setRearrangeMode(!rearrangeMode)}
            className={`w-12 h-6 rounded-full transition-colors relative ${rearrangeMode ? 'bg-blue-600' : 'bg-gray-300'}`}
          >
            <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${rearrangeMode ? 'translate-x-6' : ''}`}></div>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
        {tables.map(table => (
          <button
            key={table.id}
            onClick={() => handleTableClick(table)}
            className={`p-6 rounded-lg border-2 transition-all flex flex-col items-center justify-center space-y-2 ${
              table.status === 'vacant' ? 'bg-green-500 border-green-600' : 
              table.status === 'occupied' ? 'bg-red-500 border-red-600' : 
              'bg-yellow-500 border-yellow-600'
            } text-white hover:scale-105 active:scale-95`}
          >
            <span className="text-2xl font-bold">{table.name}</span>
            <span className="text-[10px] uppercase font-bold tracking-widest">{table.status}</span>
            {table.orderValue && <span className="text-sm">₹{table.orderValue.toFixed(2)}</span>}
          </button>
        ))}
      </div>

      {selectedTable && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] flex overflow-hidden shadow-2xl">
            {/* Menu Section */}
            <div className="flex-1 p-6 border-r overflow-y-auto">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold">New Order - {selectedTable.name}</h3>
                <div className="relative">
                  <input type="text" placeholder="Search menu..." className="pl-4 pr-10 py-2 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                {menu.map(item => (
                  <button
                    key={item.id}
                    onClick={() => addToCart(item)}
                    className="p-3 border rounded-lg hover:border-blue-500 text-left transition-colors flex justify-between items-center"
                  >
                    <div>
                      <div className="text-sm font-bold">{item.name}</div>
                      <div className="text-xs text-gray-500">₹{item.price}</div>
                    </div>
                    <div className={`w-2 h-2 rounded-full ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                  </button>
                ))}
              </div>
            </div>

            {/* Cart Section */}
            <div className="w-80 bg-gray-50 flex flex-col">
              <div className="p-4 border-b flex justify-between items-center bg-white">
                <span className="font-bold">Current Order</span>
                <button onClick={() => setSelectedTable(null)}><X className="w-5 h-5 text-gray-400" /></button>
              </div>

              <div className="flex-1 p-4 overflow-y-auto space-y-3">
                {cart.length === 0 ? (
                  <div className="text-center text-gray-400 py-10">No items selected</div>
                ) : cart.map(item => (
                  <div key={item.id} className="bg-white p-3 rounded-lg shadow-sm flex justify-between items-center">
                    <div className="flex-1">
                      <div className="text-xs font-bold">{item.name}</div>
                      <div className="text-[10px] text-gray-500">₹{item.price} × {item.qty}</div>
                    </div>
                    <div className="flex items-center space-x-2">
                      <button onClick={() => removeFromCart(item.id)} className="p-1 text-red-500 hover:bg-red-50"><Minus className="w-4 h-4" /></button>
                      <span className="text-sm font-bold">{item.qty}</span>
                      <button onClick={() => addToCart(item as MenuItem)} className="p-1 text-green-500 hover:bg-green-50"><Plus className="w-4 h-4" /></button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="p-4 bg-white border-t space-y-3">
                <div className="flex justify-between text-sm">
                  <span>Subtotal</span>
                  <span>₹{calculateTotal().subtotal.toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span>GST (5%)</span>
                  <span>₹{calculateTotal().tax.toFixed(2)}</span>
                </div>
                <div className="flex justify-between font-bold text-lg pt-2 border-t">
                  <span>Total</span>
                  <span className="text-blue-600">₹{calculateTotal().total.toFixed(2)}</span>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <button 
                    onClick={() => handlePlaceOrder('pending')}
                    disabled={cart.length === 0}
                    className="py-3 bg-gray-800 text-white rounded-lg text-sm font-bold disabled:opacity-50"
                  >
                    Punch KOT
                  </button>
                  <button 
                    onClick={() => handlePlaceOrder('billed')}
                    disabled={cart.length === 0}
                    className="py-3 bg-yellow-500 text-white rounded-lg text-sm font-bold disabled:opacity-50"
                  >
                    Bill Only
                  </button>
                </div>
                <button 
                  onClick={() => handlePlaceOrder('paid', 'UPI')}
                  disabled={cart.length === 0}
                  className="w-full py-4 bg-blue-600 text-white rounded-lg font-bold flex items-center justify-center disabled:opacity-50"
                >
                  <Check className="w-5 h-5 mr-2" /> Complete Payment
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DineIn;

import React, { useState } from 'react';
import { MenuItem, FoodType } from '../types';
import { Edit2, Trash2, Plus, Upload, Download } from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu, onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);

  const filtered = menu.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDelete = (id: string) => {
    if (confirm('Delete this item?')) {
      onUpdate(menu.filter(i => i.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: MenuItem = {
      id: editingItem?.id || Math.random().toString(36).substr(2, 9),
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      price: parseFloat(formData.get('price') as string),
      foodType: formData.get('foodType') as FoodType,
    };

    if (editingItem) {
      onUpdate(menu.map(i => i.id === editingItem.id ? newItem : i));
    } else {
      onUpdate([...menu, newItem]);
    }
    setIsModalOpen(false);
    setEditingItem(null);
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-100 overflow-hidden">
      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-xl font-bold">Menu Items</h2>
        <div className="flex flex-wrap gap-2">
          <input 
            type="text" 
            placeholder="Search menu items..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="px-4 py-2 border rounded-lg text-sm w-full md:w-64"
          />
          <button className="flex items-center px-4 py-2 text-sm font-medium text-gray-600 bg-gray-100 rounded-lg hover:bg-gray-200">
            <Upload className="w-4 h-4 mr-2" /> Bulk Upload
          </button>
          <button className="flex items-center px-4 py-2 text-sm font-medium text-gray-600 bg-gray-100 rounded-lg hover:bg-gray-200">
            <Download className="w-4 h-4 mr-2" /> Export
          </button>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700"
          >
            <Plus className="w-4 h-4 mr-2" /> Add Item
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-500 text-xs uppercase font-bold tracking-wider">
            <tr>
              <th className="px-6 py-4">Name</th>
              <th className="px-6 py-4">Category</th>
              <th className="px-6 py-4">Price</th>
              <th className="px-6 py-4">Food Type</th>
              <th className="px-6 py-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.map(item => (
              <tr key={item.id} className="hover:bg-gray-50 transition-colors">
                <td className="px-6 py-4 font-medium text-gray-800">{item.name}</td>
                <td className="px-6 py-4 text-gray-500">{item.category}</td>
                <td className="px-6 py-4 font-bold text-gray-800">₹{item.price.toFixed(2)}</td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                    item.foodType === 'veg' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                  }`}>
                    <div className={`w-1.5 h-1.5 rounded-full mr-1.5 ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                    {item.foodType === 'veg' ? 'Veg' : 'Non-veg'}
                  </span>
                </td>
                <td className="px-6 py-4 text-right space-x-2">
                  <button 
                    onClick={() => { setEditingItem(item); setIsModalOpen(true); }}
                    className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                  >
                    <Edit2 className="w-4 h-4" />
                  </button>
                  <button 
                    onClick={() => handleDelete(item.id)}
                    className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-md overflow-hidden shadow-2xl">
            <div className="p-6 border-b flex justify-between items-center">
              <h3 className="text-xl font-bold">{editingItem ? 'Edit Item' : 'Add New Item'}</h3>
              <button onClick={() => { setIsModalOpen(false); setEditingItem(null); }}><X className="w-6 h-6 text-gray-400" /></button>
            </div>
            <form onSubmit={handleSave} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Item Name</label>
                <input name="name" defaultValue={editingItem?.name} required className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
                <input name="category" defaultValue={editingItem?.category} required className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Price (₹)</label>
                  <input name="price" type="number" step="0.01" defaultValue={editingItem?.price} required className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Food Type</label>
                  <select name="foodType" defaultValue={editingItem?.foodType || 'veg'} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">
                    <option value="veg">Veg</option>
                    <option value="non-veg">Non-veg</option>
                  </select>
                </div>
              </div>
              <button type="submit" className="w-full py-3 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-colors">
                Save Item
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

