import React, { useState, useRef } from 'react';
import { MenuItem, FoodType } from '../types';
import { Edit2, Trash2, Plus, Upload, Download, X } from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu, onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = menu.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDelete = (id: string) => {
    if (confirm('Delete this item?')) {
      onUpdate(menu.filter(i => i.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: MenuItem = {
      id: editingItem?.id || Math.random().toString(36).substr(2, 9),
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      price: parseFloat(formData.get('price') as string),
      foodType: formData.get('foodType') as FoodType,
    };

    if (editingItem) {
      onUpdate(menu.map(i => i.id === editingItem.id ? newItem : i));
    } else {
      onUpdate([...menu, newItem]);
    }
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleExport = () => {
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const rows = menu.map(item => [
      item.name,
      item.category,
      item.price,
      item.foodType
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `menu_export_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadTemplate = () => {
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const exampleRow = ['Example Item', 'STARTERS', '199.00', 'veg'];
    const csvContent = [headers.join(','), exampleRow.join(',')].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'menu_upload_template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      const lines = text.split('\n');
      const newItems: MenuItem[] = [];

      // Skip header, parse lines
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const [name, category, price, foodType] = line.split(',').map(s => s.trim());

        if (name && category && price) {
          newItems.push({
            id: Math.random().toString(36).substr(2, 9),
            name,
            category,
            price: parseFloat(price),
            foodType: (foodType?.toLowerCase() === 'non-veg' ? 'non-veg' : 'veg') as FoodType,
          });
        }
      }

      if (newItems.length > 0) {
        onUpdate([...menu, ...newItems]);
        alert(`Successfully imported ${newItems.length} items.`);
      } else {
        alert('No valid items found in the file.');
      }

      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-100 overflow-hidden">
      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-xl font-bold">Menu Items</h2>
        <div className="flex flex-wrap items-center gap-3">
          <input 
            type="text" 
            placeholder="Search menu items..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />

          <div className="flex items-center gap-2">
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleBulkUpload} 
              accept=".csv" 
              className="hidden" 
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex items-center px-4 py-2 text-sm font-semibold text-gray-700 bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 transition-colors"
            >
              <Upload className="w-4 h-4 mr-2" /> Bulk Upload
            </button>

            <button 
              onClick={handleExport}
              className="flex items-center px-4 py-2 text-sm font-semibold text-gray-700 bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 transition-colors"
            >
              <Download className="w-4 h-4 mr-2" /> Export
            </button>

            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center px-6 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-shadow shadow-sm"
            >
              <Plus className="w-4 h-4 mr-2" /> Add Item
            </button>
          </div>
        </div>
      </div>

      <div className="bg-blue-50 px-6 py-2 flex justify-between items-center">
        <p className="text-[10px] font-bold text-blue-600 uppercase tracking-widest">Bulk Import Instructions: Use CSV format (Name, Category, Price, FoodType)</p>
        <button onClick={downloadTemplate} className="text-[10px] font-bold text-blue-700 underline uppercase tracking-widest hover:text-blue-800">Download Template</button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-500 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">Name</th>
              <th className="px-6 py-4">Category</th>
              <th className="px-6 py-4">Price</th>
              <th className="px-6 py-4">Food Type</th>
              <th className="px-6 py-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-12 text-center text-gray-400 font-medium">No items found matching your criteria</td>
              </tr>
            ) : filtered.map(item => (
              <tr key={item.id} className="hover:bg-gray-50 transition-colors group">
                <td className="px-6 py-4 font-bold text-gray-800 text-sm">{item.name}</td>
                <td className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">{item.category}</td>
                <td className="px-6 py-4 font-black text-gray-800 text-sm">₹{item.price.toFixed(2)}</td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-widest ${
                    item.foodType === 'veg' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'
                  }`}>
                    <div className={`w-1.5 h-1.5 rounded-full mr-1.5 ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                    {item.foodType === 'veg' ? 'Veg' : 'Non-veg'}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button 
                      onClick={() => { setEditingItem(item); setIsModalOpen(true); }}
                      className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                      title="Edit Item"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => handleDelete(item.id)}
                      className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                      title="Delete Item"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-lg font-bold text-gray-800">{editingItem ? 'Edit Menu Item' : 'New Menu Item'}</h3>
              <button onClick={() => { setIsModalOpen(false); setEditingItem(null); }} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                <X className="w-5 h-5 text-gray-500" />
              </button>
            </div>
            <form onSubmit={handleSave} className="p-6 space-y-5">
              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Item Name</label>
                <input 
                  name="name" 
                  defaultValue={editingItem?.name} 
                  required 
                  placeholder="e.g. Classic Burger"
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-medium" 
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Category</label>
                <input 
                  name="category" 
                  defaultValue={editingItem?.category} 
                  required 
                  placeholder="e.g. STARTERS"
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-medium uppercase" 
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Price (₹)</label>
                  <input 
                    name="price" 
                    type="number" 
                    step="0.01" 
                    defaultValue={editingItem?.price} 
                    required 
                    placeholder="0.00"
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold" 
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Food Type</label>
                  <select 
                    name="foodType" 
                    defaultValue={editingItem?.foodType || 'veg'} 
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold"
                  >
                    <option value="veg">Veg</option>
                    <option value="non-veg">Non-veg</option>
                  </select>
                </div>
              </div>
              <div className="pt-2">
                <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95">
                  {editingItem ? 'Update Menu Item' : 'Create Menu Item'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

