import React, { useState, useRef } from 'react';
import { MenuItem, FoodType } from '../types';
import { Edit2, Trash2, Plus, Upload, Download, X, AlertCircle } from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu, onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = menu.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this item?')) {
      onUpdate(menu.filter(i => i.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: MenuItem = {
      id: editingItem?.id || Math.random().toString(36).substr(2, 9),
      name: formData.get('name') as string,
      category: (formData.get('category') as string).toUpperCase(),
      price: parseFloat(formData.get('price') as string),
      foodType: formData.get('foodType') as FoodType,
    };

    if (editingItem) {
      onUpdate(menu.map(i => i.id === editingItem.id ? newItem : i));
    } else {
      onUpdate([...menu, newItem]);
    }
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleExport = () => {
    if (menu.length === 0) {
      alert("No items to export.");
      return;
    }
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const rows = menu.map(item => [
      `"${item.name.replace(/"/g, '""')}"`,
      `"${item.category.replace(/"/g, '""')}"`,
      item.price,
      item.foodType
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `menu_export_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadTemplate = () => {
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const exampleRows = [
      ['Classic Burger', 'BURGERS', '249.00', 'veg'],
      ['Chicken Wings', 'STARTERS', '310.00', 'non-veg']
    ];
    const csvContent = [
      headers.join(','), 
      ...exampleRows.map(r => r.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'menu_upload_template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Improved CSV parser that handles quotes and commas within fields
  const parseCSVLine = (text: string) => {
    const result = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < text.length; i++) {
      const char = text[i];
      if (char === '"' && text[i + 1] === '"') {
        cur += '"';
        i++;
      } else if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        result.push(cur.trim());
        cur = '';
      } else {
        cur += char;
      }
    }
    result.push(cur.trim());
    return result;
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File is empty or missing data rows.");

        const newItems: MenuItem[] = [];
        // Skip header
        for (let i = 1; i < lines.length; i++) {
          const parts = parseCSVLine(lines[i]);
          if (parts.length < 3) continue;

          const [name, category, priceStr, foodTypeStr] = parts;
          const price = parseFloat(priceStr);

          if (name && category && !isNaN(price)) {
            newItems.push({
              id: Math.random().toString(36).substr(2, 9) + Date.now(),
              name: name,
              category: category.toUpperCase(),
              price: price,
              foodType: (foodTypeStr?.toLowerCase().includes('non') ? 'non-veg' : 'veg') as FoodType,
            });
          }
        }

        if (newItems.length > 0) {
          onUpdate(newItems);
          alert(`Success! Replaced existing menu with ${newItems.length} fresh items.`);
        } else {
          alert('Error: No valid items found in the CSV. Please check the template.');
        }
      } catch (err) {
        alert('Error parsing CSV file. Please ensure it is a valid CSV.');
        console.error(err);
      } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-100 overflow-hidden">
      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-xl font-bold text-gray-800">Menu Catalog</h2>

        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full md:w-64">
            <input 
              type="text" 
              placeholder="Search items..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 pr-10"
            />
          </div>

          <div className="flex items-center gap-2">
            {/* Hidden file input with better accessibility / safety */}
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleBulkUpload} 
              accept=".csv" 
              style={{ position: 'absolute', width: 1, height: 1, opacity: 0, overflow: 'hidden' }}
              tabIndex={-1}
            />

            <button 
              type="button"
              onClick={() => {
                if(window.confirm("WARNING: Bulk upload will DELETE all current menu items and load fresh data from the file. Do you want to continue?")) {
                  fileInputRef.current?.click();
                }
              }}
              className="flex items-center px-4 py-2 text-sm font-bold text-gray-700 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-gray-300 transition-all shadow-sm active:scale-95"
            >
              <Upload className="w-4 h-4 mr-2 text-blue-600" /> Bulk Upload
            </button>

            <button 
              type="button"
              onClick={handleExport}
              className="flex items-center px-4 py-2 text-sm font-bold text-gray-700 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-gray-300 transition-all shadow-sm active:scale-95"
            >
              <Download className="w-4 h-4 mr-2 text-green-600" /> Export
            </button>

            <button 
              type="button"
              onClick={() => { setEditingItem(null); setIsModalOpen(true); }}
              className="flex items-center px-6 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-all shadow-md active:scale-95 ml-2"
            >
              <Plus className="w-4 h-4 mr-2" /> Add Item
            </button>
          </div>
        </div>
      </div>

      <div className="bg-amber-50 px-6 py-3 border-b border-amber-100 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <div className="flex items-center text-[11px] font-bold text-amber-700 uppercase tracking-wider">
          <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
          <span>Upload a CSV file to refresh the entire menu. Existing items will be removed.</span>
        </div>
        <button 
          onClick={downloadTemplate} 
          className="text-[10px] font-black text-blue-700 underline uppercase tracking-widest hover:text-blue-900 bg-white px-3 py-1.5 rounded-md border border-blue-100 shadow-sm transition-colors"
        >
          Download CSV Template
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-500 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">Item Name</th>
              <th className="px-6 py-4">Category</th>
              <th className="px-6 py-4">Price</th>
              <th className="px-6 py-4">Type</th>
              <th className="px-6 py-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center">
                  <div className="flex flex-col items-center justify-center opacity-40">
                    <Upload className="w-12 h-12 mb-3" />
                    <p className="font-bold text-gray-500">No menu items found</p>
                    <p className="text-xs mt-1 uppercase tracking-widest">Click 'Add Item' or use 'Bulk Upload'</p>
                  </div>
