import React, { useState, useRef } from 'react';
import { MenuItem, FoodType } from '../types';
import { Edit2, Trash2, Plus, Upload, Download, X, AlertCircle } from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu, onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = menu.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this item?')) {
      onUpdate(menu.filter(i => i.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: MenuItem = {
      id: editingItem?.id || Math.random().toString(36).substr(2, 9),
      name: formData.get('name') as string,
      category: (formData.get('category') as string).toUpperCase(),
      price: parseFloat(formData.get('price') as string),
      foodType: formData.get('foodType') as FoodType,
    };

    if (editingItem) {
      onUpdate(menu.map(i => i.id === editingItem.id ? newItem : i));
    } else {
      onUpdate([...menu, newItem]);
    }
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleExport = () => {
    if (menu.length === 0) {
      alert("No items to export.");
      return;
    }
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const rows = menu.map(item => [
      `"${item.name.replace(/"/g, '""')}"`,
      `"${item.category.replace(/"/g, '""')}"`,
      item.price,
      item.foodType
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `menu_export_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadTemplate = () => {
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const exampleRows = [
      ['Veggie Wrap', 'SAN', '149.00', 'veg'],
      ['Mexican Elote (Cheese Corn Balls)', 'STARTERS', '199.00', 'veg'],
      ['One Pan Garlic chicken', 'STARTERS', '299.00', 'non-veg']
    ];
    const csvContent = [
      headers.join(','), 
      ...exampleRows.map(r => r.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'menu_upload_template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const parseCSVLine = (text: string) => {
    const result = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < text.length; i++) {
      const char = text[i];
      if (char === '"' && text[i + 1] === '"') {
        cur += '"';
        i++;
      } else if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        result.push(cur.trim());
        cur = '';
      } else {
        cur += char;
      }
    }
    result.push(cur.trim());
    return result;
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        // Strip UTF-8 BOM if present
        const sanitizedText = text.replace(/^\uFEFF/, '');
        const lines = sanitizedText.split(/\r?\n/).filter(line => line.trim() !== '');

        if (lines.length < 2) {
          alert("CSV file must have a header row and at least one data row.");
          return;
        }

        const newItems: MenuItem[] = [];
        // Header is expected: Name, Category, Price, FoodType
        for (let i = 1; i < lines.length; i++) {
          const parts = parseCSVLine(lines[i]);
          if (parts.length < 3) continue;

          const [name, category, priceStr, foodTypeStr] = parts;
          const price = parseFloat(priceStr.replace(/[^0-9.]/g, ''));

          if (name && category && !isNaN(price)) {
            newItems.push({
              id: `item_${Date.now()}_${i}_${Math.random().toString(36).substr(2, 5)}`,
              name: name.replace(/^"|"$/g, ''),
              category: category.replace(/^"|"$/g, '').toUpperCase(),
              price: price,
              foodType: (foodTypeStr?.toLowerCase().includes('non') ? 'non-veg' : 'veg') as FoodType,
            });
          }
        }

        if (newItems.length > 0) {
          // Replace existing items with new items
          onUpdate(newItems);
          alert(`Success! Menu has been reset. ${newItems.length} fresh items loaded.`);
        } else {
          alert('No valid menu items found in the CSV. Please ensure you are using the correct template.');
        }
      } catch (err) {
        alert('An error occurred while reading the file. Please ensure it is a valid CSV.');
        console.error(err);
      } finally {
        // Reset the file input so the same file can be uploaded again if needed
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.onerror = () => {
      alert("Failed to read file.");
    };
    reader.readAsText(file);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
