        <h2 className="text-xl font-bold text-gray-800">Menu Catalog</h2>

        <div className="flex flex-wrap items-center gap-2">
          <div className="relative w-full md:w-64 mr-2">
            <input 
              type="text" 
              placeholder="Search items..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <button 
            type="button"
            onClick={() => {
              if (window.confirm("Bulk upload will PERMANENTLY DELETE all existing menu items and replace them with the data from your file. Are you sure you want to proceed?")) {
                fileInputRef.current?.click();
              }
            }}
            className="flex items-center px-4 py-2 text-sm font-semibold text-gray-600 bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 hover:text-gray-900 transition-all active:scale-95"
          >
            <Upload className="w-4 h-4 mr-2 text-blue-500" /> Bulk Upload
          </button>

          <button 
            type="button"
            onClick={handleExport}
            className="flex items-center px-4 py-2 text-sm font-semibold text-gray-600 bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 hover:text-gray-900 transition-all active:scale-95"
          >
            <Download className="w-4 h-4 mr-2 text-green-500" /> Export
          </button>

          <button 
            type="button"
            onClick={() => { setEditingItem(null); setIsModalOpen(true); }}
            className="flex items-center px-6 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-all shadow-md active:scale-95"
          >
            <Plus className="w-4 h-4 mr-2" /> Add Item
          </button>
        </div>
      </div>

      <div className="bg-amber-50 px-6 py-3 border-b border-amber-100 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <div className="flex items-center text-[11px] font-bold text-amber-700 uppercase tracking-wider">
          <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
          <span>UPLOAD A CSV FILE TO REFRESH THE ENTIRE MENU. EXISTING ITEMS WILL BE REMOVED.</span>
        </div>
        <button 
          onClick={downloadTemplate} 
          className="text-[10px] font-black text-blue-700 underline uppercase tracking-widest hover:text-blue-900 bg-white px-3 py-1.5 rounded-md border border-blue-100 shadow-sm transition-colors"
        >
          DOWNLOAD CSV TEMPLATE
        </button>
