import React, { useState, useRef } from 'react';
import { MenuItem, FoodType } from '../types';
import { Edit2, Trash2, Plus, Upload, Download, X, AlertCircle } from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu, onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = (menu || []).filter(item => 
    item && (
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
    )
  );

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this item?')) {
      onUpdate(menu.filter(i => i.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: MenuItem = {
      id: editingItem?.id || Math.random().toString(36).substr(2, 9),
      name: formData.get('name') as string,
      category: (formData.get('category') as string).toUpperCase(),
      price: parseFloat(formData.get('price') as string) || 0,
      foodType: formData.get('foodType') as FoodType,
    };

    if (editingItem) {
      onUpdate(menu.map(i => i.id === editingItem.id ? newItem : i));
    } else {
      onUpdate([...menu, newItem]);
    }
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleExport = () => {
    if (!menu || menu.length === 0) {
      alert("No items to export.");
      return;
    }
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const rows = menu.map(item => [
      `"${item.name.replace(/"/g, '""')}"`,
      `"${item.category.replace(/"/g, '""')}"`,
      item.price || 0,
      item.foodType
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `menu_export_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadTemplate = () => {
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const exampleRows = [
      ['Veggie Wrap', 'SAN', '149.00', 'veg'],
      ['Mexican Elote (Cheese Corn Balls)', 'STARTERS', '199.00', 'veg'],
      ['One Pan Garlic chicken', 'STARTERS', '299.00', 'non-veg']
    ];
    const csvContent = [
      headers.join(','), 
      ...exampleRows.map(r => r.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'menu_upload_template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const parseCSVLine = (text: string) => {
    const result = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < text.length; i++) {
      const char = text[i];
      if (char === '"' && text[i + 1] === '"') {
        cur += '"';
        i++;
      } else if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        result.push(cur.trim());
        cur = '';
      } else {
        cur += char;
      }
    }
    result.push(cur.trim());
    return result;
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        const sanitizedText = text.replace(/^\uFEFF/, '');
        const lines = sanitizedText.split(/\r?\n/).filter(line => line.trim() !== '');

        if (lines.length < 2) {
          alert("CSV file must have a header row and at least one data row.");
          return;
        }

        const newItems: MenuItem[] = [];
        for (let i = 1; i < lines.length; i++) {
          const parts = parseCSVLine(lines[i]);
          if (parts.length < 3) continue;

          const [name, category, priceStr, foodTypeStr] = parts;
          const price = parseFloat(priceStr.replace(/[^0-9.]/g, ''));

          if (name && category && !isNaN(price)) {
            newItems.push({
              id: `item_${Date.now()}_${i}_${Math.random().toString(36).substr(2, 5)}`,
              name: name.replace(/^"|"$/g, ''),
              category: category.replace(/^"|"$/g, '').toUpperCase(),
              price: price,
              foodType: (foodTypeStr?.toLowerCase().includes('non') ? 'non-veg' : 'veg') as FoodType,
            });
          }
        }

        if (newItems.length > 0) {
          onUpdate(newItems);
          alert(`Success! Menu has been reset. ${newItems.length} fresh items loaded.`);
        } else {
          alert('No valid menu items found in the CSV. Please ensure you are using the correct template.');
        }
      } catch (err) {
        alert('An error occurred while reading the file.');
        console.error(err);
      } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <input type="file" ref={fileInputRef} onChange={handleBulkUpload} accept=".csv" className="hidden" />

      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-xl font-bold text-gray-800">Menu Catalog</h2>

        <div className="flex flex-wrap items-center gap-2">
          <div className="relative w-full md:w-64 mr-2">
            <input 
              type="text" 
              placeholder="Search items..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <button 
            type="button"
            onClick={() => {
              if (window.confirm("Bulk upload will replace all existing menu items. Proceed?")) {
                fileInputRef.current?.click();
              }
            }}
            className="flex items-center px-4 py-2 text-sm font-semibold text-gray-600 bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 transition-all active:scale-95"
          >
            <Upload className="w-4 h-4 mr-2 text-blue-500" /> Bulk Upload
          </button>

          <button 
            type="button"
            onClick={handleExport}
            className="flex items-center px-4 py-2 text-sm font-semibold text-gray-600 bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 transition-all active:scale-95"
          >
            <Download className="w-4 h-4 mr-2 text-green-500" /> Export
          </button>

          <button 
            type="button"
            onClick={() => { setEditingItem(null); setIsModalOpen(true); }}
            className="flex items-center px-6 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-all shadow-md active:scale-95"
          >
            <Plus className="w-4 h-4 mr-2" /> Add Item
          </button>
        </div>
      </div>

      <div className="bg-amber-50 px-6 py-3 border-b border-amber-100 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <div className="flex items-center text-[11px] font-bold text-amber-700 uppercase tracking-wider">
          <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
          <span>UPLOAD A CSV FILE TO REFRESH THE ENTIRE MENU. EXISTING ITEMS WILL BE REMOVED.</span>
        </div>
        <button onClick={downloadTemplate} className="text-[10px] font-black text-blue-700 underline hover:text-blue-900 uppercase">
          DOWNLOAD CSV TEMPLATE
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">ITEM NAME</th>
              <th className="px-6 py-4">CATEGORY</th>
              <th className="px-6 py-4">PRICE</th>
              <th className="px-6 py-4">TYPE</th>
              <th className="px-6 py-4 text-right">ACTIONS</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-gray-400">No items available</td>
              </tr>
            ) : filtered.map(item => (
              <tr key={item.id} className="hover:bg-gray-50/50 transition-colors group">
                <td className="px-6 py-4 font-bold text-gray-900 text-sm">{item.name}</td>
                <td className="px-6 py-4">
                  <span className="text-[10px] font-bold text-gray-500 bg-gray-100 px-2 py-1 rounded uppercase tracking-wider">{item.category}</span>
                </td>
                <td className="px-6 py-4 font-black text-gray-900 text-sm">₹{(item.price ?? 0).toFixed(2)}</td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${
                    item.foodType === 'veg' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'
                  }`}>
                    <div className={`w-1.5 h-1.5 rounded-full mr-1.5 ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                    {item.foodType === 'veg' ? 'VEG' : 'NON-VEG'}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all">
                    <button onClick={() => { setEditingItem(item); setIsModalOpen(true); }} className="p-2 text-gray-400 hover:text-blue-600 transition-colors">
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button onClick={() => handleDelete(item.id)} className="p-2 text-gray-400 hover:text-red-600 transition-colors">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-lg font-bold text-gray-800">{editingItem ? 'Update Menu Item' : 'New Menu Item'}</h3>
              <button onClick={() => { setIsModalOpen(false); setEditingItem(null); }} className="p-2 hover:bg-gray-200 rounded-full">
                <X className="w-5 h-5 text-gray-500" />
              </button>
            </div>
            <form onSubmit={handleSave} className="p-6 space-y-5">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ITEM NAME</label>
                <input name="name" defaultValue={editingItem?.name} required placeholder="Classic Chicken Sandwich" className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">CATEGORY</label>
                <input name="category" defaultValue={editingItem?.category} required placeholder="SANDWICHES" className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800 uppercase" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">PRICE (₹)</label>
                  <input name="price" type="number" step="0.01" defaultValue={editingItem?.price} required className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-black text-gray-900" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">TYPE</label>
                  <select name="foodType" defaultValue={editingItem?.foodType || 'veg'} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 font-bold text-gray-800">
                    <option value="veg">Vegetarian</option>
                    <option value="non-veg">Non-Vegetarian</option>
                  </select>
                </div>
              </div>
              <div className="pt-4">
                <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-xl font-black text-sm uppercase tracking-widest hover:bg-blue-700 shadow-lg active:scale-95 transition-all">
                  {editingItem ? 'Update Item' : 'Create Item'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MenuMgmt;

import React, { useState, useMemo } from 'react';
import { Table, MenuItem, Order, OrderItem, PaymentMethod } from '../types';
import { Plus, Minus, X, Check, ArrowLeft, Trash2, Search } from 'lucide-react';

interface DineInProps {
  tables: Table[];
  menu: MenuItem[];
  onOrderComplete: (order: Order, tableId: string) => void;
  onTableUpdate: (tableId: string, updates: Partial<Table>) => void;
}

const DineIn: React.FC<DineInProps> = ({ tables, menu, onOrderComplete, onTableUpdate }) => {
  const [rearrangeMode, setRearrangeMode] = useState(false);
  const [selectedTable, setSelectedTable] = useState<Table | null>(null);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [discount, setDiscount] = useState(0);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [isClearModalOpen, setIsClearModalOpen] = useState(false);

  const categories = useMemo(() => {
    const items = menu || [];
    const cats = Array.from(new Set(items.map(item => item?.category).filter(Boolean)));
    return ['All', ...cats];
  }, [menu]);

  const filteredMenu = useMemo(() => {
    const items = menu || [];
    return items.filter(item => {
      if (!item) return false;
      const matchesCategory = selectedCategory === 'All' || item.category === selectedCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [menu, selectedCategory, searchQuery]);

  const handleTableClick = (table: Table) => {
    if (rearrangeMode) return;
    setSelectedTable(table);
    setCart([]); 
  };

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price || 0, qty: 1 }];
    });
  };

  const updateCartQty = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === itemId) {
        return { ...i, qty: Math.max(0, i.qty + delta) };
      }
      return i;
    }).filter(i => i.qty > 0));
  };

  const removeItem = (itemId: string) => {
    setCart(prev => prev.filter(i => i.id !== itemId));
  };

  const clearOrder = () => {
    setCart([]);
    setIsClearModalOpen(false);
  };

  const calculateTotal = () => {
    const subtotal = cart.reduce((sum, i) => sum + (Number(i.price) || 0) * (Number(i.qty) || 0), 0);
    const tax = 0; 
    const total = subtotal - (Number(discount) || 0);
    return { subtotal, tax, total };
  };

  const handlePlaceOrder = (status: 'pending' | 'billed' | 'paid', payment: PaymentMethod = '-') => {
    if (!selectedTable || cart.length === 0) return;
    const { subtotal, tax, total } = calculateTotal();
    const order: Order = {
      id: `#${Math.floor(Math.random() * 1000)}`,
      tableId: selectedTable.id,
      tableName: selectedTable.name,
      items: cart,
      subtotal,
      tax,
      discount: Number(discount) || 0,
      total,
      status: status as any,
      paymentMethod: payment,
      createdAt: Date.now()
    };

    onOrderComplete(order, selectedTable.id);

    const tableStatus = status === 'paid' ? 'vacant' : (status === 'billed' ? 'billed' : 'occupied');
    onTableUpdate(selectedTable.id, { 
      status: tableStatus, 
      orderValue: status === 'paid' ? undefined : total 
    });

    setSelectedTable(null);
  };

  const formatPrice = (val: number | null | undefined) => {
    return (Number(val) || 0).toFixed(2);
  };

  if (selectedTable) {
    const totals = calculateTotal();
    return (
      <div className="flex h-[calc(100vh-140px)] -m-8">
        <div className="flex-1 bg-white p-6 overflow-y-auto border-r border-gray-200">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-bold text-gray-800">Table: {selectedTable.name}</h2>
            <button 
              onClick={() => setSelectedTable(null)}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg flex items-center text-sm font-semibold hover:bg-blue-700 transition-colors"
            >
              <ArrowLeft className="w-4 h-4 mr-2" /> Back to Floor Plan
            </button>
          </div>

          <div className="flex items-center space-x-2 mb-6 overflow-x-auto pb-2 scrollbar-hide">
            <div className="relative w-64 mr-4">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input 
                type="text" 
                placeholder="Search menu..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-colors whitespace-nowrap border ${
                  selectedCategory === cat 
                    ? 'bg-blue-600 border-blue-600 text-white' 
                    : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5 gap-4">
            {filteredMenu.map(item => (
              <div key={item.id} className="bg-white border border-gray-100 rounded-xl p-4 flex flex-col justify-between hover:shadow-md transition-shadow group relative">
                <div className="flex justify-between items-start mb-2">
                   <div>
                    <h4 className="text-sm font-bold text-gray-800 leading-tight">{item.name}</h4>
                    <span className="text-[10px] text-gray-400 font-bold uppercase mt-1 block">{item.category}</span>
                   </div>
                   <div className={`w-3 h-3 border border-gray-200 rounded-sm flex items-center justify-center p-0.5`}>
                      <div className={`w-full h-full rounded-full ${item.foodType === 'veg' ? 'bg-green-600' : 'bg-red-600'}`}></div>
                   </div>
                </div>
                <div className="mt-4">
                  <div className="text-sm font-bold text-gray-800">₹{formatPrice(item.price)}</div>
                  <button 
                    onClick={() => addToCart(item)}
                    className="mt-3 w-full py-2 bg-green-100 text-green-700 text-xs font-bold rounded-lg hover:bg-green-600 hover:text-white transition-colors border border-green-200"
                  >
                    Add
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="w-[400px] bg-white flex flex-col border-l border-gray-200 shadow-xl z-10">
          <div className="p-6 border-b border-gray-100">
            <h3 className="text-lg font-bold text-gray-800">Current Order</h3>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {cart.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-40 text-gray-400">
                <p className="text-sm font-medium">Your cart is empty</p>
              </div>
            ) : (
              cart.map(item => (
                <div key={item.id} className="flex justify-between items-center group">
                  <div className="flex-1">
                    <h5 className="text-sm font-bold text-gray-800">{item.name}</h5>
                    <div className="text-xs text-gray-400">₹ {formatPrice(item.price)}</div>
                  </div>
                  <div className="flex items-center space-x-3">
                    <div className="flex items-center border border-gray-200 rounded-lg overflow-hidden bg-white">
                      <button onClick={() => updateCartQty(item.id, -1)} className="p-1 px-2 hover:bg-gray-50 text-gray-400"><Minus className="w-3 h-3" /></button>
                      <span className="px-3 text-xs font-bold text-gray-800">{item.qty}</span>
                      <button onClick={() => updateCartQty(item.id, 1)} className="p-1 px-2 hover:bg-gray-50 text-gray-400"><Plus className="w-3 h-3" /></button>
                    </div>
                    <button onClick={() => removeItem(item.id)} className="p-1.5 text-red-100 hover:text-red-500 bg-red-50 rounded-lg transition-colors">
                      <Trash2 className="w-3 h-3" />
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>

          <div className="p-6 bg-gray-50 border-t border-gray-100 space-y-4">
            <div className="space-y-2">
              <div className="flex justify-between text-sm text-gray-600">
                <span className="font-medium">Subtotal</span>
                <span className="font-bold">₹{formatPrice(totals.subtotal)}</span>
              </div>
              <div className="flex justify-between text-sm text-gray-600">
                <span className="font-medium">Discount</span>
                <span className="font-bold">0</span>
              </div>
              <div className="flex justify-between items-center pt-2 border-t border-gray-200">
                <span className="text-base font-bold text-gray-800">Total</span>
                <span className="text-xl font-bold text-gray-900">₹{formatPrice(totals.total)}</span>
              </div>
              <div className="flex justify-between text-[10px] text-gray-400 font-bold uppercase">
                <span>Duration</span>
                <span>0 min</span>
              </div>
            </div>

            <div className="space-y-2 pt-2">
              <button className="w-full py-3 bg-[#eab308] text-white rounded-lg text-xs font-bold hover:bg-[#ca8a04] transition-colors">
                Add MISC Charges
              </button>
              <button 
                onClick={() => handlePlaceOrder('pending')}
                className="w-full py-3 bg-[#facc15] text-white rounded-lg text-xs font-bold hover:bg-[#eab308] transition-colors"
              >
                Place / Update Order
              </button>
              <div className="grid grid-cols-2 gap-2">
                <button 
                  onClick={() => handlePlaceOrder('billed')}
                  className="py-3 bg-[#93c5fd] text-blue-800 rounded-lg text-xs font-bold hover:bg-[#60a5fa] transition-colors"
                >
                  Print Bill
                </button>
                <button 
                  onClick={() => handlePlaceOrder('paid', 'UPI')}
                  className="py-3 bg-[#1e3a8a] text-white rounded-lg text-xs font-bold hover:bg-[#1e40af] transition-colors"
                >
                  Settle Payment
                </button>
              </div>
              <button 
                onClick={() => setIsClearModalOpen(true)}
                className="w-full py-3 bg-[#ef4444] text-white rounded-lg text-xs font-bold hover:bg-[#dc2626] transition-colors"
              >
                Clear Order
              </button>
            </div>
          </div>
        </div>

        {isClearModalOpen && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl w-full max-w-sm overflow-hidden shadow-2xl p-8">
              <h3 className="text-lg font-bold text-gray-900 mb-2">Are you sure?</h3>
              <p className="text-sm text-gray-500 mb-8 leading-relaxed">
                This action cannot be undone. This will clear all items from the current order.
              </p>
              <div className="flex justify-end space-x-3">
                <button 
                  onClick={() => setIsClearModalOpen(false)}
                  className="px-6 py-2 border border-gray-200 rounded-lg text-sm font-bold text-gray-600 hover:bg-gray-50 transition-colors"
                >
                  No
                </button>
                <button 
                  onClick={clearOrder}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition-colors"
                >
                  Yes, Clear
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-lg shadow-sm border border-gray-100">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Floor Plan</h2>
          <div className="flex items-center mt-2 space-x-4">
            <div className="flex items-center text-[10px] font-bold uppercase tracking-wider text-gray-500">
              <div className="w-3 h-3 bg-green-500 rounded-full mr-2"></div> Vacant
            </div>
            <div className="flex items-center text-[10px] font-bold uppercase tracking-wider text-gray-500">
              <div className="w-3 h-3 bg-red-500 rounded-full mr-2"></div> Occupied
            </div>
            <div className="flex items-center text-[10px] font-bold uppercase tracking-wider text-gray-500">
              <div className="w-3 h-3 bg-yellow-500 rounded-full mr-2"></div> Billed
            </div>
          </div>
        </div>
        <div className="flex items-center">
          <span className="mr-3 text-sm font-bold text-gray-600">Rearrange Mode</span>
          <button 
            onClick={() => setRearrangeMode(!rearrangeMode)}
            className={`w-12 h-6 rounded-full transition-colors relative ${rearrangeMode ? 'bg-blue-600' : 'bg-gray-300'}`}
          >
            <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${rearrangeMode ? 'translate-x-6' : ''}`}></div>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-4">
        {tables.map(table => (
          <button
            key={table.id}
            onClick={() => handleTableClick(table)}
            className={`p-6 h-32 rounded-2xl border-2 transition-all flex flex-col items-center justify-center space-y-1 shadow-sm ${
              table.status === 'vacant' ? 'bg-green-500 border-green-600' : 
              table.status === 'occupied' ? 'bg-red-500 border-red-600' : 
              'bg-yellow-500 border-yellow-600'
            } text-white hover:scale-105 active:scale-95`}
          >
            <span className="text-2xl font-black">{table.name}</span>
            <span className="text-[10px] uppercase font-black tracking-widest opacity-80">{table.status}</span>
            {table.orderValue !== undefined && table.orderValue !== null && (
              <span className="text-xs font-bold pt-1">₹{formatPrice(table.orderValue)}</span>
            )}
          </button>
        ))}
      </div>
    </div>
  );
};

