  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Check extension
    const extension = file.name.split('.').pop()?.toLowerCase();
    if (extension !== 'csv') {
      alert(`Invalid file type: .${extension}. Please upload a standard .csv file.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text || text.trim().length === 0) {
          alert("The uploaded file is empty.");
          return;
        }

        // Remove Byte Order Mark (BOM) for Excel-generated CSVs
        const content = text.startsWith('\uFEFF') ? text.slice(1) : text;

        // Split into lines and filter empty ones
        const rows = content.split(/\r?\n/).map(row => row.trim()).filter(row => row.length > 0);

        if (rows.length < 2) {
          alert("CSV must contain a header row and at least one item.");
          return;
        }

        const items: MenuItem[] = [];
        const parsingErrors: string[] = [];

        for (let i = 1; i < rows.length; i++) {
          try {
            const columns = parseCSVLine(rows[i]);

            // Expected format: Name, Category, Price, [FoodType]
            if (columns.length < 3) {
              parsingErrors.push(`Row ${i + 1}: Insufficient columns (found ${columns.length}, expected at least 3).`);
              continue;
            }

            const name = columns[0].trim().replace(/^"|"$/g, '');
            const category = columns[1].trim().replace(/^"|"$/g, '').toUpperCase();
            const priceStr = columns[2].replace(/[^0-9.]/g, '');
            const price = parseFloat(priceStr);
            const foodTypeRaw = columns[3] ? columns[3].trim().toLowerCase().replace(/^"|"$/g, '') : 'veg';
            const foodType: FoodType = (foodTypeRaw.includes('non') || foodTypeRaw.includes('nv')) ? 'non-veg' : 'veg';

            if (!name) {
              parsingErrors.push(`Row ${i + 1}: Item name is missing.`);
              continue;
            }
            if (!category) {
              parsingErrors.push(`Row ${i + 1}: Category is missing.`);
              continue;
            }
            if (isNaN(price)) {
              parsingErrors.push(`Row ${i + 1}: Invalid price format "${columns[2]}".`);
              continue;
            }

            items.push({
              id: `csv_${Date.now()}_${i}_${Math.random().toString(36).substr(2, 5)}`,
              name,
              category,
              price,
              foodType
            });
          } catch (rowErr) {
            parsingErrors.push(`Row ${i + 1}: Critical parsing error.`);
            console.error(`Error parsing row ${i + 1}:`, rowErr);
          }
        }

        if (items.length > 0) {
          onUpdate(items);
          let msg = `Success! Imported ${items.length} menu items.`;
          if (parsingErrors.length > 0) {
            msg += `\n\nNote: ${parsingErrors.length} rows were skipped due to formatting errors. Open browser console for details.`;
            console.warn("Bulk Upload Warnings:", parsingErrors);
          }
          alert(msg);
        } else {
          let errorMsg = "Could not parse any valid items from the CSV.";
          if (parsingErrors.length > 0) {
            errorMsg += "\n\nTop Errors:\n" + parsingErrors.slice(0, 5).join('\n');
            if (parsingErrors.length > 5) errorMsg += `\n... and ${parsingErrors.length - 5} more errors.`;
          }
          alert(errorMsg);
        }
      } catch (err) {
        alert("An unexpected error occurred during the import process.");
        console.error("Import Exception:", err);
      } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.onerror = () => alert("Could not read the file. Please check file permissions.");
    reader.readAsText(file);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleBulkUpload} 
        accept=".csv" 
