  messagingSenderId: "your-sender-id",
  appId: "your-app-id"
};

const app = initializeApp(firebaseConfig);
export const firestore = getFirestore(app);

class FirestoreService {
  // Real-time Listeners
  subscribeToTables(callback: (tables: Table[]) => void) {
    return onSnapshot(collection(firestore, 'tables'), (snapshot) => {
      const tables = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Table));
      if (tables.length === 0) {
        // Initialize tables if collection is empty
        this.initializeTables();
      }
      callback(tables.sort((a, b) => a.name.localeCompare(b.name)));
    });
  }

  subscribeToMenu(callback: (menu: MenuItem[]) => void) {
    return onSnapshot(collection(firestore, 'menu_items'), (snapshot) => {
      const menu = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as MenuItem));
      if (menu.length === 0) {
        this.initializeMenu();
      }
      callback(menu);
    });
  }

  subscribeToOrders(callback: (orders: Order[]) => void) {
    const q = query(collection(firestore, 'orders'), orderBy('createdAt', 'desc'), limit(100));
    return onSnapshot(q, (snapshot) => {
      const orders = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      callback(orders);
    });
  }

  // Initializers (One-time setup)
  private async initializeTables() {
    const batch = writeBatch(firestore);
    INITIAL_TABLES.forEach(table => {
      const ref = doc(firestore, 'tables', table.id);
      batch.set(ref, table);
    });
    await batch.commit();
  }

  private async initializeMenu() {
    const batch = writeBatch(firestore);
    INITIAL_MENU.forEach(item => {
      const ref = doc(firestore, 'menu_items', item.id);
      batch.set(ref, item);
    });
    await batch.commit();
  }

  // CRUD Operations
  async updateTable(tableId: string, updates: Partial<Table>) {
    const ref = doc(firestore, 'tables', tableId);
    await updateDoc(ref, updates);
  }

  async createOrder(order: Order) {
    await addDoc(collection(firestore, 'orders'), {
      ...order,
      createdAt: Date.now() // Ensure server-side consistent timing
    });
  }

  async updateMenu(items: MenuItem[]) {
    // For bulk updates, we clear and replace
    const batch = writeBatch(firestore);
    // Note: In production, you'd delete existing first or update selectively
    items.forEach(item => {
