const app = initializeApp(firebaseConfig);
export const firestore = getFirestore(app);

class FirestoreService {
  // Real-time Listeners
  subscribeToTables(callback: (tables: Table[]) => void) {
    return onSnapshot(collection(firestore, 'tables'), (snapshot) => {
      const tables = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Table));
      if (tables.length === 0) {
        this.initializeTables();
      }
      callback(tables.sort((a, b) => a.name.localeCompare(b.name)));
    }, (error) => {
      console.error("Firestore tables subscription error:", error);
    });
  }

  subscribeToMenu(callback: (menu: MenuItem[]) => void) {
    return onSnapshot(collection(firestore, 'menu_items'), (snapshot) => {
      const menu = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as MenuItem));
      if (menu.length === 0) {
        this.initializeMenu();
      }
      callback(menu);
    }, (error) => {
      console.error("Firestore menu subscription error:", error);
    });
  }

  subscribeToOrders(callback: (orders: Order[]) => void) {
    const q = query(collection(firestore, 'orders'), orderBy('createdAt', 'desc'), limit(100));
    return onSnapshot(q, (snapshot) => {
      const orders = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      callback(orders);
    }, (error) => {
      console.error("Firestore orders subscription error:", error);
    });
  }

  // Initializers (One-time setup if collection is empty)
  private async initializeTables() {
    console.log("Initializing tables in Firestore...");
    const batch = writeBatch(firestore);
    INITIAL_TABLES.forEach(table => {
      const ref = doc(firestore, 'tables', table.id);
      batch.set(ref, table);
    });
    await batch.commit();
  }

  private async initializeMenu() {
    console.log("Initializing menu in Firestore...");
    const batch = writeBatch(firestore);
    INITIAL_MENU.forEach(item => {
      const ref = doc(firestore, 'menu_items', item.id);
      batch.set(ref, item);
    });
    await batch.commit();
  }

  // Connectivity Test
  async testConnection(): Promise<boolean> {
    try {
      const snap = await getDocs(query(collection(firestore, 'tables'), limit(1)));
      console.log("Firestore Connection Test: SUCCESS");
      return true;
    } catch (err) {
      console.error("Firestore Connection Test: FAILED", err);
      return false;
    }
  }

  // CRUD Operations
  async updateTable(tableId: string, updates: Partial<Table>) {
    const ref = doc(firestore, 'tables', tableId);
    await updateDoc(ref, updates);
  }

  async createOrder(order: Order) {
    await addDoc(collection(firestore, 'orders'), {
      ...order,
      createdAt: Date.now()
    });
  }

  async updateMenu(items: MenuItem[]) {
    const batch = writeBatch(firestore);
    items.forEach(item => {
      const ref = doc(firestore, 'menu_items', item.id);
      batch.set(ref, item);
    });
    await batch.commit();
  }

  async deleteMenuItem(id: string) {
    const ref = doc(firestore, 'menu_items', id);
    await deleteDoc(ref);
  }

  // Profile & Settings
  async getProfile(): Promise<BusinessProfile> {
    try {
      const ref = doc(firestore, 'config', 'profile');
      const snap = await getDoc(ref);
      if (snap.exists()) {
        return snap.data() as BusinessProfile;
      } else {
        await setDoc(ref, INITIAL_PROFILE);
        return INITIAL_PROFILE;
      }
    } catch (e) {
      console.warn("Could not fetch profile from Firestore, using defaults.");
      return INITIAL_PROFILE;
    }
  }

  async updateProfile(p: BusinessProfile) {
    const ref = doc(firestore, 'config', 'profile');
    await setDoc(ref, p);
  }
}

export const db = new FirestoreService();

