        // Skip header row (index 0)
        for (let i = 1; i < allRows.length; i++) {
          const columns = allRows[i];

          // Basic validation: Expecting [Name, Category, Price, FoodType]
          if (columns.length < 3) {
            errors.push(`Row ${i + 1}: Not enough columns (found ${columns.length}, expected at least 3).`);
            continue;
          }

          const name = columns[0].trim();
          const category = columns[1].trim().toUpperCase();
          const priceStr = columns[2].replace(/[^0-9.]/g, ''); // Clean price string
          const price = parseFloat(priceStr);
          const foodTypeRaw = columns[3]?.toLowerCase() || 'veg';

          // Flexible FoodType mapping
          let foodType: FoodType = 'veg';
          if (foodTypeRaw.includes('non') || foodTypeRaw.includes('nv') || foodTypeRaw === 'n') {
            foodType = 'non-veg';
          }

          if (!name) {
            errors.push(`Row ${i + 1}: Name is missing.`);
            continue;
          }
          if (!category) {
            errors.push(`Row ${i + 1}: Category is missing.`);
            continue;
          }
          if (isNaN(price)) {
            errors.push(`Row ${i + 1}: Invalid price "${columns[2]}".`);
            continue;
          }

          items.push({
            id: `csv_${Date.now()}_${i}_${Math.random().toString(36).substr(2, 5)}`,
            name,
            category,
            price,
            foodType
          });
        }

        if (items.length > 0) {
          onUpdate(items); // Replace existing menu
          let message = `Success! Imported ${items.length} items.`;
          if (errors.length > 0) {
            message += `\n\nSkipped ${errors.length} rows due to errors:\n- ` + errors.slice(0, 3).join('\n- ');
            if (errors.length > 3) message += `\n... and ${errors.length - 3} more errors.`;
          }
          alert(message);
        } else {
          alert("Failed to parse any valid items. Please check the CSV format.\n\nErrors:\n" + errors.slice(0, 5).join('\n'));
        }
      } catch (err) {
        console.error("CSV Import Error:", err);
        alert("An unexpected error occurred during CSV processing. Please ensure the file is valid.");
      } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.onerror = () => alert("Could not read the file. Please check file permissions.");
    reader.readAsText(file);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
