        const items: MenuItem[] = [];
        const errors: string[] = [];

        for (let i = 1; i < allRows.length; i++) {
          const columns = allRows[i];

          if (columns.length < 3) {
            errors.push(`Row ${i + 1}: Incomplete data (Columns found: ${columns.length})`);
            continue;
