              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <button 
            type="button"
            disabled={isImporting}
            onClick={() => fileInputRef.current?.click()}
            className={`flex items-center px-4 py-2 text-[14px] font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all active:scale-95 shadow-sm ${isImporting ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {isImporting ? (
              <Loader2 className="w-5 h-5 mr-2 text-blue-500 animate-spin" />
