        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">ITEM NAME</th>
              <th className="px-6 py-4">CATEGORY</th>
              <th className="px-6 py-4">PRICE</th>
              <th className="px-6 py-4">TYPE</th>
              <th className="px-6 py-4 text-right">ACTIONS</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-gray-400 font-medium">No menu items found.</td>
              </tr>
            ) : filtered.map(item => (
              <tr key={item.id} className="hover:bg-gray-50/80 transition-colors group">
                <td className="px-6 py-4 font-bold text-gray-900 text-sm">{item.name}</td>
                <td className="px-6 py-4">
                  <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-2 py-1 rounded uppercase tracking-wider">
                    {item.category}
                  </span>
                </td>
                <td className="px-6 py-4 font-black text-gray-900 text-sm">₹{(item.price ?? 0).toFixed(2)}</td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${
                    item.foodType === 'veg' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'
                  }`}>
                    <div className={`w-1.5 h-1.5 rounded-full mr-1.5 ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                    {item.foodType === 'veg' ? 'VEG' : 'NON-VEG'}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-2">
                    <button 
                      onClick={() => { setEditingItem(item); setIsModalOpen(true); }} 
                      className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                      title="Edit Item"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => handleDelete(item.id)} 
                      className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                      title="Delete Item"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-lg font-bold text-gray-800">{editingItem ? 'Update Menu Item' : 'New Menu Item'}</h3>
              <button onClick={() => { setIsModalOpen(false); setEditingItem(null); }} className="p-2 hover:bg-gray-200 rounded-full">
                <X className="w-5 h-5 text-gray-500" />
              </button>
            </div>
            <form key={editingItem?.id || 'new'} onSubmit={handleSave} className="p-6 space-y-5">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ITEM NAME</label>
                <input name="name" defaultValue={editingItem?.name} required placeholder="Classic Chicken Sandwich" className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">CATEGORY</label>
                <input name="category" defaultValue={editingItem?.category} required placeholder="SANDWICHES" className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800 uppercase" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">PRICE (₹)</label>
                  <input name="price" type="number" step="0.01" defaultValue={editingItem?.price} required className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-black text-gray-900" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">TYPE</label>
                  <select name="foodType" defaultValue={editingItem?.foodType || 'veg'} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 font-bold text-gray-800">
                    <option value="veg">Vegetarian</option>
                    <option value="non-veg">Non-Vegetarian</option>
                  </select>
                </div>
              </div>
              <div className="pt-4">
                <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-xl font-black text-sm uppercase tracking-widest hover:bg-blue-700 shadow-lg active:scale-95 transition-all">
                  {editingItem ? 'Update Item' : 'Create Item'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MenuMgmt;

import React, { useState, useRef, useMemo } from 'react';
import { MenuItem, FoodType } from '../types';
import { Edit2, Trash2, Plus, Upload, Download, X, AlertCircle, Loader2, Save } from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu = [], onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Memoized filtered menu to prevent unnecessary recalculations
  const filtered = useMemo(() => {
    return (menu || []).filter(item => 
      item && (
        item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.category.toLowerCase().includes(searchTerm.toLowerCase())
      )
    );
  }, [menu, searchTerm]);

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleDelete = (id: string) => {
    const itemToDelete = menu.find(i => i.id === id);
    if (!itemToDelete) return;

    if (window.confirm(`Are you sure you want to delete "${itemToDelete.name}"? This action cannot be undone.`)) {
      const updatedMenu = menu.filter(i => i.id !== id);
      onUpdate(updatedMenu);
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const name = (formData.get('name') as string || '').trim();
    const category = (formData.get('category') as string || 'GENERAL').trim().toUpperCase();
    const price = parseFloat(formData.get('price') as string) || 0;
    const foodType = formData.get('foodType') as FoodType;

    if (!name) {
      alert("Please enter an item name.");
      return;
    }

    const newItem: MenuItem = {
      id: editingItem?.id || `item_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
      name,
      category,
      price,
      foodType,
    };

    let updatedMenu: MenuItem[];
    if (editingItem) {
      // Update existing
      updatedMenu = menu.map(i => i.id === editingItem.id ? newItem : i);
    } else {
      // Add new
      updatedMenu = [...menu, newItem];
    }

    onUpdate(updatedMenu);
    closeModal();
  };

  const handleExport = () => {
    if (!menu || menu.length === 0) {
      alert("No items to export.");
      return;
    }
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const rows = menu.map(item => [
      `"${(item.name || '').replace(/"/g, '""')}"`,
      `"${(item.category || '').replace(/"/g, '""')}"`,
      item.price || 0,
      item.foodType
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `rock_bottom_menu_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadTemplate = () => {
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const exampleRows = [
      ['Classic Burger', 'BURGERS', '199.00', 'veg'],
      ['Grilled Chicken Sandwich', 'SANDWICH', '249.00', 'non-veg'],
      ['"Pasta Arrabbiata, Red Sauce"', 'PASTA', '299.00', 'veg']
    ];
    const csvContent = [
      headers.join(','), 
      ...exampleRows.map(r => r.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'menu_import_template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const parseCSV = (csvText: string) => {
    const rows: string[][] = [];
    let currentRow: string[] = [];
    let currentField = '';
    let inQuotes = false;

    for (let i = 0; i < csvText.length; i++) {
      const char = csvText[i];
      const nextChar = csvText[i + 1];

      if (inQuotes) {
        if (char === '"' && nextChar === '"') {
          currentField += '"';
          i++; 
        } else if (char === '"') {
          inQuotes = false;
        } else {
          currentField += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          currentRow.push(currentField.trim());
          currentField = '';
        } else if (char === '\n' || char === '\r') {
          if (char === '\r' && nextChar === '\n') i++; 
          currentRow.push(currentField.trim());
          if (currentRow.length > 0 && currentRow.some(f => f !== '')) {
            rows.push(currentRow);
          }
          currentRow = [];
          currentField = '';
        } else {
          currentField += char;
        }
      }
    }
    if (currentField !== '' || currentRow.length > 0) {
      currentRow.push(currentField.trim());
      if (currentRow.some(f => f !== '')) {
        rows.push(currentRow);
      }
    }
    return rows;
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const extension = file.name.split('.').pop()?.toLowerCase();
    if (extension !== 'csv') {
      alert(`Invalid File: .${extension} is not supported. Please upload a standard CSV file.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!window.confirm(`Warning: Uploading "${file.name}" will REPLACE ALL ${menu.length} current menu items. Do you want to proceed?`)) {
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsImporting(true);

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text || text.trim().length === 0) {
          alert("Error: The selected file is empty.");
          setIsImporting(false);
          return;
        }

        const cleanText = text.startsWith('\uFEFF') ? text.slice(1) : text;
        const allRows = parseCSV(cleanText);

        if (allRows.length < 2) {
          alert("Format Error: The CSV must contain a header row and at least one item.");
          setIsImporting(false);
          return;
        }

        const items: MenuItem[] = [];
        const errors: string[] = [];

        for (let i = 1; i < allRows.length; i++) {
          const columns = allRows[i];
          if (columns.length < 3) continue;

          const name = columns[0]?.trim();
          const category = columns[1]?.trim().toUpperCase();
          const priceRaw = columns[2] || "0";
          const priceStr = priceRaw.replace(/[₹$,]/g, '').trim();
          const price = parseFloat(priceStr);
          const foodTypeRaw = (columns[3] || 'veg').toLowerCase();

          let foodType: FoodType = 'veg';
          if (foodTypeRaw.includes('non') || foodTypeRaw.includes('nv') || foodTypeRaw === 'n') {
            foodType = 'non-veg';
          }

          if (name && category && !isNaN(price)) {
            items.push({
              id: `csv_${Date.now()}_${i}_${Math.random().toString(36).substr(2, 5)}`,
              name,
              category,
              price,
              foodType
            });
          } else {
            errors.push(`Row ${i + 1}: Check formatting.`);
          }
        }

        if (items.length > 0) {
          onUpdate(items);
          alert(`Success: Imported ${items.length} items. ${errors.length > 0 ? `(${errors.length} rows failed)` : ''}`);
        } else {
          alert("Import Failed: No valid items found in CSV.");
        }
      } catch (err) {
        console.error("CSV Import Error:", err);
        alert("Failed to process CSV file.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleBulkUpload} 
        accept=".csv" 
        className="hidden" 
      />

      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-xl font-bold text-gray-800">Menu Management</h2>

        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full md:w-64">
            <input 
              type="text" 
              placeholder="Search items..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <button 
            type="button"
            disabled={isImporting}
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center px-4 py-2 text-[14px] font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all active:scale-95 shadow-sm disabled:opacity-50"
          >
            {isImporting ? <Loader2 className="w-5 h-5 mr-2 animate-spin" /> : <Upload className="w-5 h-5 mr-2 text-blue-500" />}
            {isImporting ? 'Processing...' : 'Bulk Import'}
          </button>

          <button 
            type="button"
            onClick={handleExport}
            className="flex items-center px-4 py-2 text-[14px] font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all active:scale-95 shadow-sm"
          >
            <Download className="w-5 h-5 mr-2 text-green-500" /> Export
          </button>

          <button 
            type="button"
            onClick={() => { setEditingItem(null); setIsModalOpen(true); }}
            className="flex items-center px-6 py-2 text-[14px] font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all shadow-md active:scale-95"
          >
            <Plus className="w-5 h-5 mr-2 stroke-[3]" /> Add New
          </button>
        </div>
      </div>

      <div className="bg-amber-50 px-6 py-3 border-b border-amber-100 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <div className="flex items-center text-[11px] font-bold text-amber-700 uppercase tracking-wider">
          <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
          <span>Careful: Bulk import overwrites the entire catalog.</span>
        </div>
        <button onClick={downloadTemplate} className="text-[10px] font-black text-blue-700 underline uppercase tracking-tighter">
          Get Import Template
        </button>
      </div>

      <div className="overflow-x-auto min-h-[400px]">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">ITEM DETAILS</th>
              <th className="px-6 py-4">CATEGORY</th>
              <th className="px-6 py-4">PRICE</th>
              <th className="px-6 py-4">FOOD TYPE</th>
              <th className="px-6 py-4 text-right">ACTIONS</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-gray-400">
                  <div className="flex flex-col items-center">
                    <BookOpen className="w-12 h-12 mb-3 opacity-20" />
                    <p className="font-medium">No menu items match your search.</p>
                  </div>
                </td>
              </tr>
            ) : filtered.map(item => (
              <tr key={item.id} className="hover:bg-gray-50/80 transition-colors">
                <td className="px-6 py-4">
                  <div className="font-bold text-gray-900 text-sm">{item.name}</div>
                  <div className="text-[10px] text-gray-400 font-medium">ID: {item.id}</div>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[10px] font-bold text-gray-500 bg-gray-100 px-2 py-1 rounded uppercase tracking-wider">
                    {item.category}
                  </span>
                </td>
                <td className="px-6 py-4 font-black text-gray-900 text-sm">₹{(item.price || 0).toFixed(2)}</td>
                <td className="px-6 py-4">
                  <div className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${
                    item.foodType === 'veg' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'
                  }`}>
                    <div className={`w-1.5 h-1.5 rounded-full mr-1.5 ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                    {item.foodType === 'veg' ? 'VEG' : 'NON-VEG'}
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-1">
                    <button 
                      onClick={() => { setEditingItem(item); setIsModalOpen(true); }} 
                      className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                      title="Edit"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => handleDelete(item.id)} 
                      className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                      title="Delete"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <div>
                <h3 className="text-lg font-bold text-gray-800">{editingItem ? 'Edit Item' : 'New Catalog Item'}</h3>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-wider mt-0.5">
                  {editingItem ? `Editing ID: ${editingItem.id}` : 'Create a fresh menu entry'}
                </p>
              </div>
              <button onClick={closeModal} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                <X className="w-5 h-5 text-gray-500" />
              </button>
            </div>

            <form key={editingItem?.id || 'new'} onSubmit={handleSave} className="p-6 space-y-5">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ITEM NAME</label>
                <input 
                  name="name" 
                  defaultValue={editingItem?.name} 
                  required 
                  autoFocus
                  placeholder="e.g., Paneer Butter Masala" 
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800" 
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">CATEGORY</label>
                <input 
                  name="category" 
                  defaultValue={editingItem?.category} 
                  required 
                  placeholder="e.g., MAIN COURSE" 
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800 uppercase" 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">PRICE (₹)</label>
                  <input 
                    name="price" 
                    type="number" 
                    step="0.01" 
                    defaultValue={editingItem?.price} 
                    required 
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-black text-gray-900" 
                  />
                </div>
                <div className="space-y-1">
