        const errors: string[] = [];

        // Skip header row
        for (let i = 1; i < allRows.length; i++) {
          const cols = allRows[i];
          if (cols.length < 3) {
            errors.push(`Row ${i + 1}: Missing columns (Name, Category, Price are mandatory)`);
            continue;
          }

          const name = cols[0]?.trim();
          const category = cols[1]?.trim().toUpperCase();
          const priceRaw = cols[2]?.replace(/[₹$,]/g, '').trim() || "0";
          const price = parseFloat(priceRaw);
          const foodTypeRaw = (cols[3] || 'veg').toLowerCase();

          let foodType: FoodType = 'veg';
          if (foodTypeRaw.includes('non') || foodTypeRaw.includes('nv') || foodTypeRaw === 'n') {
            foodType = 'non-veg';
          }

          if (!name) {
            errors.push(`Row ${i + 1}: Name is empty`);
            continue;
          }
          if (!category) {
            errors.push(`Row ${i + 1}: Category is empty`);
            continue;
          }
          if (isNaN(price)) {
            errors.push(`Row ${i + 1}: Invalid price "${cols[2]}"`);
            continue;
          }

          newItems.push({
            id: `item_${Date.now()}_${i}_${Math.random().toString(36).substr(2, 4)}`,
            name,
            category,
            price,
            foodType
          });
        }

        if (newItems.length > 0) {
          onUpdate(newItems);
          const errorSummary = errors.length > 0 
            ? `\n\nSkipped ${errors.length} invalid rows:\n- ${errors.slice(0, 5).join('\n- ')}${errors.length > 5 ? '\n...and more.' : ''}`
            : '';

          alert(`Success! Imported ${newItems.length} items.${errorSummary}`);
        } else {
          alert(`Import Failed: No valid menu items found.\n\nErrors:\n${errors.slice(0, 10).join('\n')}`);
        }
      } catch (err: any) {
        console.error("CSV Import Error:", err);
        alert(`Critical Error: ${err.message || 'Failed to process file'}`);
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.onerror = () => {
      alert("Error: Failed to read the file.");
      setIsImporting(false);
    };

    reader.readAsText(file);
  };

  const handleExport = () => {
    if (!menu || menu.length === 0) {
      alert("Nothing to export.");
      return;
    }
    const headers = ['Name', 'Category', 'Price', 'FoodType'];
    const csvContent = [
      headers.join(','),
      ...menu.map(item => [
        `"${(item.name || '').replace(/"/g, '""')}"`,
        `"${(item.category || '').replace(/"/g, '""')}"`,
        item.price || 0,
        item.foodType
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `rock_bottom_menu_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const downloadTemplate = () => {
    const csv = 'Name,Category,Price,FoodType\n"Classic Veg Burger","BURGERS",120.00,"veg"\n"Crispy Chicken Wings","STARTERS",250.00,"non-veg"';
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'menu_template.csv';
    link.click();
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleBulkUpload} 
        accept=".csv" 
        className="hidden" 
      />

      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Menu Catalog</h2>
          <p className="text-xs text-gray-500 mt-1">Manage items, prices, and categories for your digital menu.</p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full md:w-64">
            <input 
              type="text" 
              placeholder="Search by name or category..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
            />
          </div>

          <button 
            type="button"
            disabled={isImporting}
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center px-4 py-2 text-[14px] font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all active:scale-95 shadow-sm disabled:opacity-50"
          >
            {isImporting ? <Loader2 className="w-5 h-5 mr-2 animate-spin text-blue-500" /> : <Upload className="w-5 h-5 mr-2 text-blue-500" />}
            {isImporting ? 'Importing...' : 'Bulk Import'}
          </button>

          <button 
            type="button"
            onClick={handleExport}
            className="flex items-center px-4 py-2 text-[14px] font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all active:scale-95 shadow-sm"
          >
            <Download className="w-5 h-5 mr-2 text-green-500" /> Export
          </button>

          <button 
            type="button"
            onClick={() => { setEditingItem(null); setIsModalOpen(true); }}
            className="flex items-center px-6 py-2 text-[14px] font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all shadow-md active:scale-95"
          >
            <Plus className="w-5 h-5 mr-2 stroke-[3]" /> Add Item
          </button>
        </div>
      </div>

      <div className="bg-blue-50 px-6 py-3 border-b border-blue-100 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <div className="flex items-center text-[11px] font-bold text-blue-700 uppercase tracking-wider">
          <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
          <span>Quick Note: Bulk import will overwrite your current menu items in Firestore.</span>
        </div>
        <button onClick={downloadTemplate} className="text-[10px] font-black text-blue-700 underline uppercase hover:text-blue-800 transition-colors">
          Download CSV Template
        </button>
      </div>

      <div className="overflow-x-auto min-h-[400px]">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">ITEM DETAILS</th>
              <th className="px-6 py-4">CATEGORY</th>
              <th className="px-6 py-4">PRICE</th>
              <th className="px-6 py-4">TYPE</th>
              <th className="px-6 py-4 text-right">ACTIONS</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-gray-400">
                  <div className="flex flex-col items-center">
                    <BookOpen className="w-12 h-12 mb-3 opacity-10" />
                    <p className="font-medium text-gray-400">No menu items found matching your criteria.</p>
                  </div>
                </td>
              </tr>
            ) : filtered.map(item => (
              <tr key={item.id} className="hover:bg-gray-50/80 transition-colors">
                <td className="px-6 py-4">
                  <div className="font-bold text-gray-900 text-sm">{item.name}</div>
                  <div className="text-[10px] text-gray-400 font-medium">ID: {item.id}</div>
