import { initializeApp, getApps, FirebaseApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  deleteDoc, 
  getDoc, 
  updateDoc, 
  query, 
  orderBy, 
  writeBatch,
  getDocs,
  Firestore
} from "firebase/firestore";
import { MenuItem, Table, Order, BusinessProfile } from '../types';
import { INITIAL_MENU, INITIAL_TABLES, INITIAL_PROFILE } from '../constants';

// Firebase configuration placeholder. 
// In most Studio/Serverless environments, this is either pre-configured 
// or injected via environment variables.
const firebaseConfig = {
  apiKey: process.env.API_KEY, // Reusing the provided API key if applicable, though usually distinct
  authDomain: "rock-bottom-pos.firebaseapp.com",
  projectId: "rock-bottom-pos",
  storageBucket: "rock-bottom-pos.appspot.com",
  messagingSenderId: "123456789",
  appId: "1:123456789:web:abcdef123456"
};

class FirestoreService {
  private db: Firestore;
  private app: FirebaseApp;

  constructor() {
    this.app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0];
    this.db = getFirestore(this.app);
    this.seedInitialData();
  }

  /**
   * Seeds the database with initial constants if collections are empty.
   */
  private async seedInitialData() {
    try {
      const menuSnap = await getDocs(collection(this.db, 'menu_items'));
      if (menuSnap.empty) {
        console.log("Seeding menu items...");
        const batch = writeBatch(this.db);
        INITIAL_MENU.forEach(item => {
          const ref = doc(this.db, 'menu_items', item.id);
          batch.set(ref, item);
        });
        await batch.commit();
      }

      const tablesSnap = await getDocs(collection(this.db, 'tables'));
      if (tablesSnap.empty) {
        console.log("Seeding tables...");
        const batch = writeBatch(this.db);
        INITIAL_TABLES.forEach(table => {
          const ref = doc(this.db, 'tables', table.id);
          batch.set(ref, table);
        });
        await batch.commit();
      }

      const profileSnap = await getDoc(doc(this.db, 'business_profile', 'cafe_settings'));
      if (!profileSnap.exists()) {
        console.log("Seeding profile...");
        await setDoc(doc(this.db, 'business_profile', 'cafe_settings'), INITIAL_PROFILE);
      }
    } catch (err) {
      console.warn("Seeding failed (likely missing config or permissions):", err);
    }
  }

  // Real-time Subscriptions
  subscribeToTables(callback: (tables: Table[]) => void) {
    const q = query(collection(this.db, 'tables'));
    return onSnapshot(q, (snapshot) => {
      const tables = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Table));
      callback(tables.sort((a, b) => a.name.localeCompare(b.name)));
    }, (error) => {
      console.error("Firestore tables error:", error);
    });
  }

  subscribeToMenu(callback: (menu: MenuItem[]) => void) {
    const q = query(collection(this.db, 'menu_items'), orderBy('category'));
    return onSnapshot(q, (snapshot) => {
      const menu = snapshot.docs.map(doc => ({ ...doc.data() } as MenuItem));
      callback(menu);
    }, (error) => {
      console.error("Firestore menu error:", error);
    });
  }

  subscribeToOrders(callback: (orders: Order[]) => void) {
    const q = query(collection(this.db, 'orders'), orderBy('createdAt', 'desc'));
    return onSnapshot(q, (snapshot) => {
      const orders = snapshot.docs.map(doc => ({ ...doc.data() } as Order));
      callback(orders);
    }, (error) => {
      console.error("Firestore orders error:", error);
    });
  }

  async testConnection(): Promise<boolean> {
    try {
      await getDoc(doc(this.db, 'business_profile', 'cafe_settings'));
      return true;
    } catch (e) {
      console.error("Connection test failed:", e);
      return false;
    }
  }

  // Operations
  async updateTable(tableId: string, updates: Partial<Table>) {
    const tableRef = doc(this.db, 'tables', tableId);
    await updateDoc(tableRef, updates);
  }

  async createOrder(order: Order) {
    const orderRef = doc(this.db, 'orders', order.id);
    await setDoc(orderRef, { ...order, createdAt: Date.now() });
  }

  /**
   * Replaces the entire menu with a new set of items (used for Bulk Import).
   */
  async updateMenu(items: MenuItem[]) {
    const batch = writeBatch(this.db);

    // 1. Get existing items to delete
    const existingItems = await getDocs(collection(this.db, 'menu_items'));
    existingItems.forEach(d => batch.delete(d.ref));

    // 2. Add new items
    items.forEach(item => {
      const ref = doc(this.db, 'menu_items', item.id);
      batch.set(ref, item);
    });

    await batch.commit();
  }

  async deleteMenuItem(id: string) {
    await deleteDoc(doc(this.db, 'menu_items', id));
  }

  async getProfile(): Promise<BusinessProfile> {
    const snap = await getDoc(doc(this.db, 'business_profile', 'cafe_settings'));
    return snap.exists() ? (snap.data() as BusinessProfile) : INITIAL_PROFILE;
  }

  async updateProfile(p: BusinessProfile) {
    await setDoc(doc(this.db, 'business_profile', 'cafe_settings'), p);
  }
}

export const db = new FirestoreService();

import React, { useState, useRef, useMemo } from 'react';
import { MenuItem, FoodType } from '../types';
import { 
  Edit2, 
  Trash2, 
  Plus, 
  Upload, 
  Download, 
  X, 
  AlertCircle, 
  Loader2, 
  Save, 
  BookOpen, 
  CheckCircle,
  Info
} from 'lucide-react';
import { db } from '../services/db';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu = [], onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return (menu || []).filter(item => {
      if (!item || typeof item.name !== 'string') return false;
      return (
        item.name.toLowerCase().includes(term) ||
        (item.category && item.category.toLowerCase().includes(term))
      );
    });
  }, [menu, searchTerm]);

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleDelete = async (id: string) => {
    const itemToDelete = menu.find(i => i.id === id);
    if (!itemToDelete) return;

    if (window.confirm(`Are you sure you want to delete "${itemToDelete.name}"? This will permanently remove it from Firestore.`)) {
      try {
        await db.deleteMenuItem(id);
        // The real-time listener in App.tsx will pick this up, 
        // but we filter locally for instant feedback if desired.
        onUpdate(menu.filter(i => i.id !== id));
      } catch (err) {
        console.error("Delete failed:", err);
        alert("Failed to delete item from database.");
      }
    }
  };

  const handleSave = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const name = (formData.get('name') as string || '').trim();
    const category = (formData.get('category') as string || 'GENERAL').trim().toUpperCase();
    const price = parseFloat(formData.get('price') as string) || 0;
    const foodType = formData.get('foodType') as FoodType;

    if (!name) {
      alert("Item name is required.");
      return;
    }

    const newItem: MenuItem = {
      id: editingItem?.id || `item_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
      name,
      category,
      price,
      foodType,
    };

    try {
      if (editingItem) {
        // We can use a direct setDoc/updateDoc through a helper or just onUpdate
        // Since onUpdate replaces the whole menu in our current App.tsx logic, 
        // we'll stick to that for now for consistency, but Firestore allows individual doc updates.
        onUpdate(menu.map(i => i.id === editingItem.id ? newItem : i));
      } else {
        onUpdate([...menu, newItem]);
      }
      closeModal();
    } catch (err) {
      console.error("Save failed:", err);
      alert("Failed to save menu item.");
    }
  };

  const parseCSV = (csvText: string) => {
    const rows: string[][] = [];
    let currentRow: string[] = [];
    let currentField = '';
    let inQuotes = false;

    for (let i = 0; i < csvText.length; i++) {
      const char = csvText[i];
      const nextChar = csvText[i + 1];

      if (inQuotes) {
        if (char === '"' && nextChar === '"') {
          currentField += '"';
          i++; 
        } else if (char === '"') {
          inQuotes = false;
        } else {
          currentField += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          currentRow.push(currentField.trim());
          currentField = '';
        } else if (char === '\n' || char === '\r') {
          if (char === '\r' && nextChar === '\n') i++; 
          currentRow.push(currentField.trim());
          if (currentRow.length > 0 && currentRow.some(f => f !== '')) {
            rows.push(currentRow);
          }
          currentRow = [];
          currentField = '';
        } else {
          currentField += char;
        }
      }
    }
    if (currentField !== '' || currentRow.length > 0) {
      currentRow.push(currentField.trim());
      if (currentRow.some(f => f !== '')) {
        rows.push(currentRow);
      }
    }
    return rows;
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.name.toLowerCase().endsWith('.csv')) {
      alert("Error: Only .csv files are supported for menu imports.");
      return;
    }

    if (!window.confirm(`Proceeding will delete ALL current items in Firestore and replace them with the data from "${file.name}". Are you sure?`)) {
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsImporting(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const text = e.target?.result as string;
        if (!text || !text.trim()) throw new Error("File is empty.");

        const cleanText = text.startsWith('\uFEFF') ? text.slice(1) : text;
        const allRows = parseCSV(cleanText);

        if (allRows.length < 2) throw new Error("CSV must contain a header and at least one data row.");

        const newItems: MenuItem[] = [];
        const errors: string[] = [];

        // CSV Format: Name, Category, Price, Type (veg/non-veg)
        for (let i = 1; i < allRows.length; i++) {
          const cols = allRows[i];
          if (cols.length < 3) continue;

          const name = cols[0]?.trim();
          const category = cols[1]?.trim().toUpperCase() || 'GENERAL';
          const priceRaw = cols[2]?.replace(/[₹$,]/g, '').trim() || "0";
          const price = parseFloat(priceRaw);
          const typeRaw = (cols[3] || 'veg').toLowerCase();

          let foodType: FoodType = 'veg';
          if (typeRaw.includes('non') || typeRaw.includes('nv') || typeRaw === 'n') {
            foodType = 'non-veg';
          }

          if (name && !isNaN(price)) {
            newItems.push({
              id: `item_${Date.now()}_${i}_${Math.random().toString(36).substr(2, 4)}`,
              name,
              category,
              price,
              foodType
            });
          } else {
            errors.push(`Row ${i + 1}: ${!name ? 'Missing Name' : 'Invalid Price'}`);
          }
        }

        if (newItems.length > 0) {
          await db.updateMenu(newItems);
          onUpdate(newItems); // Refresh local state
          alert(`Successfully imported ${newItems.length} items. ${errors.length > 0 ? `(${errors.length} errors found)` : ''}`);
        } else {
          alert("Import failed: No valid menu items found in CSV.");
        }
      } catch (err: any) {
        console.error("Bulk Upload Error:", err);
        alert(`Critical Error: ${err.message || 'Parsing failed'}`);
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

  const handleExport = () => {
    if (!menu || menu.length === 0) {
      alert("No menu data to export.");
      return;
    }
    const headers = ['Name', 'Category', 'Price', 'Type'];
    const csv = [
      headers.join(','),
      ...menu.map(i => [
        `"${i.name.replace(/"/g, '""')}"`,
        `"${i.category.replace(/"/g, '""')}"`,
        i.price,
        i.foodType
      ].join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `rock_bottom_menu_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden relative">
      {isImporting && (
        <div className="absolute inset-0 bg-white/80 z-[60] flex flex-col items-center justify-center backdrop-blur-sm">
          <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-4" />
          <p className="font-bold text-blue-800">Synchronizing with Cloud Firestore...</p>
          <p className="text-xs text-blue-600 mt-2">Writing data batch, please wait.</p>
        </div>
      )}

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleBulkUpload} 
        accept=".csv" 
        className="hidden" 
      />

      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Menu Catalog</h2>
          <p className="text-xs text-gray-500 mt-1">Found {filtered.length} items in current view.</p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full md:w-64">
            <input 
              type="text" 
              placeholder="Filter by name or category..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
            />
          </div>

          <button 
            type="button"
            disabled={isImporting}
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center px-4 py-2 text-[14px] font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all active:scale-95 shadow-sm disabled:opacity-50"
          >
            <Upload className="w-5 h-5 mr-2 text-blue-500 stroke-[2.5]" /> Bulk Import
          </button>

          <button 
            type="button"
            onClick={handleExport}
            className="flex items-center px-4 py-2 text-[14px] font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all active:scale-95 shadow-sm"
          >
            <Download className="w-5 h-5 mr-2 text-green-500 stroke-[2.5]" /> Export
          </button>

          <button 
            type="button"
            onClick={() => { setEditingItem(null); setIsModalOpen(true); }}
            className="flex items-center px-6 py-2 text-[14px] font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all shadow-md active:scale-95"
          >
            <Plus className="w-5 h-5 mr-2 stroke-[3]" /> Add Item
          </button>
        </div>
      </div>

      <div className="bg-blue-50/50 px-6 py-3 border-b border-blue-100 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <div className="flex items-center text-[10px] font-bold text-blue-700 uppercase tracking-widest">
          <Info className="w-4 h-4 mr-2 flex-shrink-0" />
          <span>REAL-TIME FIRESTORE SYNC IS ACTIVE</span>
        </div>
        <button 
          onClick={() => {
            const csv = 'Name,Category,Price,Type\n"Paneer Tikka","STARTERS",250.00,"veg"\n"Chicken Wrap","SANDWICHES",180.00,"non-veg"';
            const blob = new Blob([csv], { type: 'text/csv' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = 'menu_template.csv';
            link.click();
          }} 
          className="text-[10px] font-black text-blue-600 underline uppercase hover:text-blue-800 transition-colors"
        >
          Download CSV Template
        </button>
      </div>

      <div className="overflow-x-auto min-h-[400px]">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">ITEM DETAILS</th>
              <th className="px-6 py-4">CATEGORY</th>
              <th className="px-6 py-4">PRICE</th>
              <th className="px-6 py-4">TYPE</th>
              <th className="px-6 py-4 text-right">ACTIONS</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-gray-400">
                  <div className="flex flex-col items-center">
                    <BookOpen className="w-12 h-12 mb-3 opacity-10" />
                    <p className="font-medium">No results found in your menu.</p>
                  </div>
                </td>
              </tr>
            ) : (
              filtered.map(item => (
                <tr key={item.id} className="hover:bg-gray-50/80 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-bold text-gray-900 text-sm">{item.name}</div>
                    <div className="text-[10px] text-gray-400 font-medium">REF: {item.id.split('_').pop()?.toUpperCase()}</div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-[10px] font-bold text-gray-500 bg-gray-100 px-2.5 py-1 rounded-md uppercase tracking-wider">
                      {item.category || 'MISC'}
                    </span>
                  </td>
                  <td className="px-6 py-4 font-black text-gray-900 text-sm">₹{(item.price || 0).toFixed(2)}</td>
                  <td className="px-6 py-4">
                    <div className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${
                      item.foodType === 'veg' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'
                    }`}>
                      <div className={`w-1.5 h-1.5 rounded-full mr-1.5 ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                      {item.foodType === 'veg' ? 'VEG' : 'NON-VEG'}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1">
                      <button 
                        onClick={() => { setEditingItem(item); setIsModalOpen(true); }} 
                        className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => handleDelete(item.id)} 
                        className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-lg font-bold text-gray-800">{editingItem ? 'Edit Item' : 'New Catalog Entry'}</h3>
              <button onClick={closeModal} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                <X className="w-5 h-5 text-gray-500" />
              </button>
            </div>

            <form key={editingItem?.id || 'new'} onSubmit={handleSave} className="p-6 space-y-5">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ITEM NAME</label>
                <input 
                  name="name" 
                  defaultValue={editingItem?.name} 
                  required 
                  autoFocus
                  placeholder="e.g., Mushroom Risotto" 
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800" 
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">CATEGORY</label>
                <input 
                  name="category" 
                  defaultValue={editingItem?.category} 
                  required 
                  placeholder="e.g., STARTERS" 
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-bold text-gray-800 uppercase" 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">PRICE (₹)</label>
                  <input 
                    name="price" 
                    type="number" 
                    step="0.01" 
                    defaultValue={editingItem?.price} 
                    required 
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none focus:bg-white transition-all font-black text-gray-900" 
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">TYPE</label>
                  <select 
                    name="foodType" 
                    defaultValue={editingItem?.foodType || 'veg'} 
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 font-bold text-gray-800"
                  >
                    <option value="veg">Vegetarian</option>
                    <option value="non-veg">Non-Vegetarian</option>
                  </select>
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <button 
                  type="button" 
                  onClick={closeModal}
                  className="flex-1 py-4 bg-gray-100 text-gray-600 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-gray-200 transition-all"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="flex-[2] py-4 bg-blue-600 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-700 shadow-lg active:scale-95 transition-all flex items-center justify-center"
                >
                  <CheckCircle className="w-4 h-4 mr-2" />
                  {editingItem ? 'Update Database' : 'Add to Catalog'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MenuMgmt;

import React, { useState, useRef, useMemo } from 'react';
import { MenuItem, FoodType } from '../types';
import { 
  Edit2, 
  Trash2, 
  Plus, 
  Upload, 
  Download, 
  X, 
  AlertCircle, 
  Loader2, 
  Save, 
  BookOpen, 
  CheckCircle,
  Info
} from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu = [], onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return (menu || []).filter(item => {
      if (!item || typeof item.name !== 'string') return false;
      return (
        item.name.toLowerCase().includes(term) ||
        (item.category && item.category.toLowerCase().includes(term))
      );
    });
  }, [menu, searchTerm]);

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleDelete = (id: string) => {
    const itemToDelete = menu.find(i => i.id === id);
    if (!itemToDelete) return;

    if (window.confirm(`Are you sure you want to delete "${itemToDelete.name}"?`)) {
      // Direct propagation to App.tsx which handles db.updateMenu
      onUpdate(menu.filter(i => i.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const name = (formData.get('name') as string || '').trim();
    const category = (formData.get('category') as string || 'GENERAL').trim().toUpperCase();
    const price = parseFloat(formData.get('price') as string) || 0;
    const foodType = formData.get('foodType') as FoodType;

    if (!name) return;

    const newItem: MenuItem = {
      id: editingItem?.id || String(Date.now()),
      name,
      category,
      price,
      foodType,
    };

    const updatedMenu = editingItem 
      ? menu.map(i => i.id === editingItem.id ? newItem : i)
      : [...menu, newItem];

    onUpdate(updatedMenu);
    closeModal();
  };

  const parseCSV = (csvText: string) => {
    const rows: string[][] = [];
    let currentRow: string[] = [];
    let currentField = '';
    let inQuotes = false;

    for (let i = 0; i < csvText.length; i++) {
      const char = csvText[i];
      const nextChar = csvText[i + 1];

      if (inQuotes) {
        if (char === '"' && nextChar === '"') {
          currentField += '"';
          i++; 
        } else if (char === '"') {
          inQuotes = false;
        } else {
          currentField += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          currentRow.push(currentField.trim());
          currentField = '';
        } else if (char === '\n' || char === '\r') {
          if (char === '\r' && nextChar === '\n') i++; 
          currentRow.push(currentField.trim());
          if (currentRow.length > 0 && currentRow.some(f => f !== '')) {
            rows.push(currentRow);
          }
          currentRow = [];
          currentField = '';
        } else {
          currentField += char;
        }
      }
    }
    if (currentField !== '' || currentRow.length > 0) {
      currentRow.push(currentField.trim());
      if (currentRow.some(f => f !== '')) {
        rows.push(currentRow);
      }
    }
    return rows;
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!window.confirm("BULK IMPORT WILL OVERWRITE YOUR CURRENT MENU ITEMS IN FIRESTORE. Proceed?")) {
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsImporting(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const text = e.target?.result as string;
        const allRows = parseCSV(text.startsWith('\uFEFF') ? text.slice(1) : text);

        if (allRows.length < 2) throw new Error("Invalid CSV");

        const newItems: MenuItem[] = [];
        for (let i = 1; i < allRows.length; i++) {
          const cols = allRows[i];
          if (cols.length < 3) continue;

          const name = cols[0]?.trim();
          const category = cols[1]?.trim().toUpperCase();
          const priceRaw = cols[2]?.replace(/[₹$,]/g, '').trim();
          const price = parseFloat(priceRaw || '0');
          const typeRaw = (cols[3] || 'veg').toLowerCase();

          if (name && !isNaN(price)) {
            newItems.push({
              id: String(i), // Consistent ID numbering for imports
              name,
              category,
              price,
              foodType: typeRaw.includes('non') ? 'non-veg' : 'veg'
            });
          }
        }

        if (newItems.length > 0) {
          onUpdate(newItems);
          alert(`Successfully imported ${newItems.length} items.`);
        }
      } catch (err) {
        alert("Failed to process CSV file.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

  const handleExport = () => {
    if (menu.length === 0) return;
    const csv = 'Name,Category,Price,Type\n' + menu.map(i => `"${i.name}","${i.category}",${i.price},${i.foodType}`).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'menu_export.csv';
    link.click();
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden relative">
      <input type="file" ref={fileInputRef} onChange={handleBulkUpload} accept=".csv" className="hidden" />

      {isImporting && (
        <div className="absolute inset-0 bg-white/60 z-50 flex flex-col items-center justify-center backdrop-blur-sm">
          <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-2" />
          <p className="font-bold text-blue-800">Processing Menu...</p>
        </div>
      )}

      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Menu Catalog</h2>
          <p className="text-xs text-gray-500 mt-1">Manage items, prices, and categories for your digital menu.</p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full md:w-64">
            <input 
              type="text" 
              placeholder="Search by name or category..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <button onClick={() => fileInputRef.current?.click()} className="flex items-center px-4 py-2 text-sm font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all shadow-sm">
            <Upload className="w-4 h-4 mr-2 text-blue-500" /> Bulk Import
          </button>

          <button onClick={handleExport} className="flex items-center px-4 py-2 text-sm font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all shadow-sm">
            <Download className="w-4 h-4 mr-2 text-green-500" /> Export
          </button>

          <button onClick={() => { setEditingItem(null); setIsModalOpen(true); }} className="flex items-center px-6 py-2 text-sm font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all shadow-md">
            <Plus className="w-5 h-5 mr-1" /> Add Item
          </button>
        </div>
      </div>

      <div className="bg-blue-50/50 px-6 py-3 border-b border-blue-100 flex items-center justify-between">
        <div className="flex items-center text-[11px] font-bold text-blue-600 uppercase tracking-wider">
          <Info className="w-4 h-4 mr-2" />
          QUICK NOTE: BULK IMPORT WILL OVERWRITE YOUR CURRENT MENU ITEMS IN FIRESTORE.
        </div>
        <button onClick={() => {
            const csv = 'Name,Category,Price,Type\n"Veggie Wrap","SAN",149.0,"veg"';
            const blob = new Blob([csv], { type: 'text/csv' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = 'menu_template.csv';
            link.click();
        }} className="text-[10px] font-bold text-blue-600 underline uppercase">DOWNLOAD CSV TEMPLATE</button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">ITEM DETAILS</th>
              <th className="px-6 py-4">CATEGORY</th>
              <th className="px-6 py-4">PRICE</th>
              <th className="px-6 py-4">TYPE</th>
              <th className="px-6 py-4 text-right">ACTIONS</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-10 text-center text-gray-400 font-medium">No results found.</td>
              </tr>
            ) : filtered.map(item => (
              <tr key={item.id} className="hover:bg-gray-50/50 transition-colors">
                <td className="px-6 py-4">
                  <div className="font-bold text-gray-900 text-sm">{item.name}</div>
                  <div className="text-[10px] text-gray-400 font-bold">ID: {item.id}</div>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[10px] font-bold text-gray-500 bg-gray-100 px-2 py-0.5 rounded uppercase tracking-tighter">
                    {item.category}
                  </span>
                </td>
                <td className="px-6 py-4 font-bold text-gray-900 text-sm">₹{item.price.toFixed(2)}</td>
                <td className="px-6 py-4">
                  <div className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${
                    item.foodType === 'veg' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'
                  }`}>
                    <div className={`w-1.5 h-1.5 rounded-full mr-2 ${item.foodType === 'veg' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                    {item.foodType === 'veg' ? 'VEG' : 'NON-VEG'}
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-2">
                    <button onClick={() => { setEditingItem(item); setIsModalOpen(true); }} className="p-2 text-gray-300 hover:text-blue-600 transition-colors">
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button onClick={() => handleDelete(item.id)} className="p-2 text-gray-300 hover:text-red-600 transition-colors">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
