import { MenuItem, Table, Order, BusinessProfile } from '../types';
import { INITIAL_MENU, INITIAL_TABLES, INITIAL_PROFILE } from '../constants';

/**
 * FIX: Replaced broken Firebase implementation with a robust localStorage-based implementation.
 * This resolves "Module 'firebase/app' has no exported member" errors while maintaining 
 * the subscription-based interface required by App.tsx.
 */
class FirestoreService {
  private storageKey = 'cafe_rock_bottom_db';

  constructor() {
    this.seedInitialData();
  }

  /**
   * Seeds the local storage with initial data if it's the first time running.
   */
  private seedInitialData() {
    try {
      if (!localStorage.getItem(`${this.storageKey}_menu_items`)) {
        localStorage.setItem(`${this.storageKey}_menu_items`, JSON.stringify(INITIAL_MENU));
      }
      if (!localStorage.getItem(`${this.storageKey}_tables`)) {
        localStorage.setItem(`${this.storageKey}_tables`, JSON.stringify(INITIAL_TABLES));
      }
      if (!localStorage.getItem(`${this.storageKey}_business_profile`)) {
        localStorage.setItem(`${this.storageKey}_business_profile`, JSON.stringify(INITIAL_PROFILE));
      }
      if (!localStorage.getItem(`${this.storageKey}_orders`)) {
        localStorage.setItem(`${this.storageKey}_orders`, JSON.stringify([]));
      }
    } catch (err) {
      console.warn("Storage seeding failed:", err);
    }
  }

  private getData<T>(key: string): T | null {
    const data = localStorage.getItem(`${this.storageKey}_${key}`);
    try {
      return data ? JSON.parse(data) : null;
    } catch (e) {
      console.error(`Error parsing ${key}:`, e);
      return null;
    }
  }

  private setData(key: string, data: any) {
    localStorage.setItem(`${this.storageKey}_${key}`, JSON.stringify(data));
    // Internal event to notify subscriptions in the same tab
    window.dispatchEvent(new Event('storage_update'));
  }

  // Real-time Subscriptions (simulated using storage events)
  subscribeToTables(callback: (tables: Table[]) => void) {
    const handler = () => {
      const tables = this.getData<Table[]>('tables') || [];
      callback([...tables].sort((a, b) => a.name.localeCompare(b.name)));
    };
    window.addEventListener('storage_update', handler);
    window.addEventListener('storage', handler);
    handler(); // Initial call
    return () => {
      window.removeEventListener('storage_update', handler);
      window.removeEventListener('storage', handler);
    };
  }

  subscribeToMenu(callback: (menu: MenuItem[]) => void) {
    const handler = () => {
      const menu = this.getData<MenuItem[]>('menu_items') || [];
      callback([...menu].sort((a, b) => a.category.localeCompare(b.category)));
    };
    window.addEventListener('storage_update', handler);
    window.addEventListener('storage', handler);
    handler();
    return () => {
      window.removeEventListener('storage_update', handler);
      window.removeEventListener('storage', handler);
    };
  }

  subscribeToOrders(callback: (orders: Order[]) => void) {
    const handler = () => {
      const orders = this.getData<Order[]>('orders') || [];
      callback([...orders].sort((a, b) => b.createdAt - a.createdAt));
    };
    window.addEventListener('storage_update', handler);
    window.addEventListener('storage', handler);
    handler();
    return () => {
      window.removeEventListener('storage_update', handler);
      window.removeEventListener('storage', handler);
    };
  }

  async testConnection(): Promise<boolean> {
    // Local storage is always available
    return true;
  }

  // Operations
  async updateTable(tableId: string, updates: Partial<Table>) {
    const tables = this.getData<Table[]>('tables') || [];
    const idx = tables.findIndex(t => t.id === tableId);
    if (idx !== -1) {
      tables[idx] = { ...tables[idx], ...updates };
      this.setData('tables', tables);
    }
  }

  async createOrder(order: Order) {
    const orders = this.getData<Order[]>('orders') || [];
    orders.unshift({ ...order, createdAt: Date.now() });
    this.setData('orders', orders);
  }

  /**
   * Replaces the entire menu with a new set of items.
   */
  async updateMenu(items: MenuItem[]) {
    this.setData('menu_items', items);
  }

  async deleteMenuItem(id: string) {
    const menu = this.getData<MenuItem[]>('menu_items') || [];
    this.setData('menu_items', menu.filter(i => i.id !== id));
  }

  async getProfile(): Promise<BusinessProfile> {
    const profile = this.getData<BusinessProfile>('business_profile');
    return profile || INITIAL_PROFILE;
  }

  async updateProfile(p: BusinessProfile) {
    this.setData('business_profile', p);
  }
}

export const db = new FirestoreService();

import React, { useState, useRef, useMemo } from 'react';
import { MenuItem, FoodType } from '../types';
import { 
  Edit2, 
  Trash2, 
  Plus, 
  Upload, 
  Download, 
  X, 
  AlertCircle, 
  Loader2, 
  Save, 
  BookOpen, 
  CheckCircle,
  Info
} from 'lucide-react';

interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu = [], onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return (menu || []).filter(item => {
      if (!item || typeof item.name !== 'string') return false;
      return (
        item.name.toLowerCase().includes(term) ||
        (item.category && item.category.toLowerCase().includes(term))
      );
    });
  }, [menu, searchTerm]);

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingItem(null);
  };

  const handleDelete = (id: string) => {
    const itemToDelete = menu.find(i => String(i.id) === String(id));
    if (!itemToDelete) {
      console.warn("Delete failed: Item not found", id);
      return;
    }

    if (window.confirm(`Are you sure you want to delete "${itemToDelete.name}"?`)) {
      // Create a fresh array reference for React to detect the change
      const updatedMenu = menu.filter(i => String(i.id) !== String(id));
      onUpdate(updatedMenu);
    }
  };

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const name = (formData.get('name') as string || '').trim();
    const category = (formData.get('category') as string || 'GENERAL').trim().toUpperCase();
    const price = parseFloat(formData.get('price') as string) || 0;
    const foodType = formData.get('foodType') as FoodType;

    if (!name) return;

    const newItem: MenuItem = {
      id: editingItem?.id || `item_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
      name,
      category,
      price,
      foodType,
    };

    const updatedMenu = editingItem 
      ? menu.map(i => i.id === editingItem.id ? newItem : i)
      : [...menu, newItem];

    onUpdate(updatedMenu);
    closeModal();
  };

  const parseCSV = (csvText: string) => {
    const rows: string[][] = [];
    let currentRow: string[] = [];
    let currentField = '';
    let inQuotes = false;

    for (let i = 0; i < csvText.length; i++) {
      const char = csvText[i];
      const nextChar = csvText[i + 1];

      if (inQuotes) {
        if (char === '"' && nextChar === '"') {
          currentField += '"';
          i++; 
        } else if (char === '"') {
          inQuotes = false;
        } else {
          currentField += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          currentRow.push(currentField.trim());
          currentField = '';
        } else if (char === '\n' || char === '\r') {
          if (char === '\r' && nextChar === '\n') i++; 
          currentRow.push(currentField.trim());
          if (currentRow.length > 0 && currentRow.some(f => f !== '')) {
            rows.push(currentRow);
          }
          currentRow = [];
          currentField = '';
        } else {
          currentField += char;
        }
      }
    }
    if (currentField !== '' || currentRow.length > 0) {
      currentRow.push(currentField.trim());
      if (currentRow.some(f => f !== '')) {
        rows.push(currentRow);
      }
    }
    return rows;
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!window.confirm("BULK IMPORT WILL OVERWRITE YOUR CURRENT MENU ITEMS IN FIRESTORE. Proceed?")) {
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsImporting(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const text = e.target?.result as string;
        const allRows = parseCSV(text.startsWith('\uFEFF') ? text.slice(1) : text);

        if (allRows.length < 2) throw new Error("Invalid CSV format: Header missing");

        const newItems: MenuItem[] = [];
        const timestamp = Date.now();

        for (let i = 1; i < allRows.length; i++) {
          const cols = allRows[i];
          if (cols.length < 3) continue;

          const name = cols[0]?.trim();
          const category = (cols[1]?.trim() || 'GENERAL').toUpperCase();
          const priceRaw = cols[2]?.replace(/[₹$,]/g, '').trim();
          const price = parseFloat(priceRaw || '0');
          const typeRaw = (cols[3] || 'veg').toLowerCase();

          if (name && !isNaN(price)) {
            newItems.push({
              // Use complex unique IDs to prevent React key reconciliation issues
              id: `bulk_${timestamp}_${i}`,
              name,
              category,
              price,
              foodType: typeRaw.includes('non') ? 'non-veg' : 'veg'
            });
          }
        }

        if (newItems.length > 0) {
          onUpdate(newItems);
          // Small delay before alert to let React finish rendering
          setTimeout(() => alert(`Successfully imported ${newItems.length} items.`), 100);
        } else {
          alert("No valid menu items found in the CSV file.");
        }
      } catch (err: any) {
        console.error("CSV Import Error:", err);
        alert(`Failed to process CSV file: ${err.message}`);
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

  const handleExport = () => {
    if (menu.length === 0) {
      alert("No menu items to export.");
      return;
    }
    const csv = 'Name,Category,Price,Type\n' + menu.map(i => `"${i.name.replace(/"/g, '""')}","${i.category.replace(/"/g, '""')}",${i.price},${i.foodType}`).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `menu_export_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden relative">
      <input type="file" ref={fileInputRef} onChange={handleBulkUpload} accept=".csv" className="hidden" />

      {isImporting && (
        <div className="absolute inset-0 bg-white/70 z-50 flex flex-col items-center justify-center backdrop-blur-sm">
          <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-2" />
          <p className="font-bold text-blue-800">Updating Cloud Catalog...</p>
        </div>
      )}

      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Menu Catalog</h2>
          <p className="text-xs text-gray-500 mt-1">Manage items, prices, and categories for your digital menu.</p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full md:w-64">
            <input 
              type="text" 
              placeholder="Search by name or category..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
            />
          </div>

          <button onClick={() => fileInputRef.current?.click()} className="flex items-center px-4 py-2 text-sm font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all shadow-sm active:scale-95">
            <Upload className="w-4 h-4 mr-2 text-blue-500" /> Bulk Import
          </button>

          <button onClick={handleExport} className="flex items-center px-4 py-2 text-sm font-semibold text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all shadow-sm active:scale-95">
            <Download className="w-4 h-4 mr-2 text-green-500" /> Export
          </button>

          <button onClick={() => { setEditingItem(null); setIsModalOpen(true); }} className="flex items-center px-6 py-2 text-sm font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all shadow-md active:scale-95">
            <Plus className="w-5 h-5 mr-1" /> Add Item
          </button>
        </div>
      </div>

      <div className="bg-blue-50/50 px-6 py-3 border-b border-blue-100 flex items-center justify-between">
        <div className="flex items-center text-[10px] font-bold text-blue-600 uppercase tracking-wider">
          <Info className="w-4 h-4 mr-2" />
          QUICK NOTE: BULK IMPORT WILL OVERWRITE YOUR CURRENT MENU ITEMS IN FIRESTORE.
        </div>
        <button onClick={() => {
            const csv = 'Name,Category,Price,Type\n"Veggie Wrap","SAN",149.0,"veg"';
            const blob = new Blob([csv], { type: 'text/csv' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = 'menu_template.csv';
            link.click();
        }} className="text-[10px] font-bold text-blue-600 underline uppercase hover:text-blue-800">DOWNLOAD CSV TEMPLATE</button>
      </div>

      <div className="overflow-x-auto min-h-[400px]">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">ITEM DETAILS</th>
              <th className="px-6 py-4">CATEGORY</th>
              <th className="px-6 py-4">PRICE</th>
              <th className="px-6 py-4">TYPE</th>
