import { MenuItem, Table, Order, BusinessProfile } from '../types';
import { INITIAL_MENU, INITIAL_TABLES, INITIAL_PROFILE } from '../constants';

/**
 * FIX: Replaced broken Firebase implementation with a robust localStorage-based implementation.
 * This resolves "Module 'firebase/app' has no exported member" errors while maintaining 
 * the subscription-based interface required by App.tsx.
 */
class FirestoreService {
  private storageKey = 'cafe_rock_bottom_db';

  constructor() {
    this.seedInitialData();
  }

  /**
   * Seeds the local storage with initial data if it's the first time running.
   */
  private seedInitialData() {
    try {
      if (!localStorage.getItem(`${this.storageKey}_menu_items`)) {
        localStorage.setItem(`${this.storageKey}_menu_items`, JSON.stringify(INITIAL_MENU));
      }
      if (!localStorage.getItem(`${this.storageKey}_tables`)) {
        localStorage.setItem(`${this.storageKey}_tables`, JSON.stringify(INITIAL_TABLES));
      }
      if (!localStorage.getItem(`${this.storageKey}_business_profile`)) {
        localStorage.setItem(`${this.storageKey}_business_profile`, JSON.stringify(INITIAL_PROFILE));
      }
      if (!localStorage.getItem(`${this.storageKey}_orders`)) {
        localStorage.setItem(`${this.storageKey}_orders`, JSON.stringify([]));
      }
    } catch (err) {
      console.warn("Storage seeding failed:", err);
    }
  }

  private getData<T>(key: string): T | null {
    const data = localStorage.getItem(`${this.storageKey}_${key}`);
    try {
      return data ? JSON.parse(data) : null;
    } catch (e) {
      console.error(`Error parsing ${key}:`, e);
      return null;
    }
  }

  private setData(key: string, data: any) {
    localStorage.setItem(`${this.storageKey}_${key}`, JSON.stringify(data));
    // Internal event to notify subscriptions in the same tab
    window.dispatchEvent(new Event('storage_update'));
  }

  // Real-time Subscriptions (simulated using storage events)
  subscribeToTables(callback: (tables: Table[]) => void) {
    const handler = () => {
      const tables = this.getData<Table[]>('tables') || [];
      callback([...tables].sort((a, b) => (a.name || '').localeCompare(b.name || '')));
    };
    window.addEventListener('storage_update', handler);
    window.addEventListener('storage', handler);
    handler(); // Initial call
    return () => {
      window.removeEventListener('storage_update', handler);
      window.removeEventListener('storage', handler);
    };
  }

  subscribeToMenu(callback: (menu: MenuItem[]) => void) {
    const handler = () => {
      const menu = this.getData<MenuItem[]>('menu_items') || [];
      // Safe sort with category fallbacks
      callback([...menu].sort((a, b) => (a.category || '').localeCompare(b.category || '')));
    };
    window.addEventListener('storage_update', handler);
    window.addEventListener('storage', handler);
    handler();
    return () => {
      window.removeEventListener('storage_update', handler);
      window.removeEventListener('storage', handler);
    };
  }

  subscribeToOrders(callback: (orders: Order[]) => void) {
    const handler = () => {
      const orders = this.getData<Order[]>('orders') || [];
      callback([...orders].sort((a, b) => b.createdAt - a.createdAt));
    };
    window.addEventListener('storage_update', handler);
    window.addEventListener('storage', handler);
    handler();
    return () => {
      window.removeEventListener('storage_update', handler);
      window.removeEventListener('storage', handler);
    };
  }

  async testConnection(): Promise<boolean> {
    // Local storage is always available
    return true;
  }

  // Operations
  async updateTable(tableId: string, updates: Partial<Table>) {
    const tables = this.getData<Table[]>('tables') || [];
    const idx = tables.findIndex(t => String(t.id) === String(tableId));
    if (idx !== -1) {
      tables[idx] = { ...tables[idx], ...updates };
      this.setData('tables', tables);
    }
  }

  async createOrder(order: Order) {
    const orders = this.getData<Order[]>('orders') || [];
    orders.unshift({ ...order, createdAt: Date.now() });
    this.setData('orders', orders);
  }

  /**
   * Replaces the entire menu with a new set of items.
   */
  async updateMenu(items: MenuItem[]) {
    this.setData('menu_items', items);
  }

  async deleteMenuItem(id: string) {
    const menu = this.getData<MenuItem[]>('menu_items') || [];
    this.setData('menu_items', menu.filter(i => String(i.id) !== String(id)));
  }

  async getProfile(): Promise<BusinessProfile> {
    const profile = this.getData<BusinessProfile>('business_profile');
    return profile || INITIAL_PROFILE;
  }

  async updateProfile(p: BusinessProfile) {
    this.setData('business_profile', p);
  }
}

export const db = new FirestoreService();

import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  deleteDoc, 
  getDoc, 
  query, 
  orderBy, 
  writeBatch,
  getDocs
} from "firebase/firestore";
import { MenuItem, Table, Order, BusinessProfile } from '../types';
import { INITIAL_MENU, INITIAL_TABLES, INITIAL_PROFILE } from '../constants';

// Firebase configuration using the provided environment API key
const firebaseConfig = {
  apiKey: process.env.API_KEY,
  authDomain: "rock-bottom-pos.firebaseapp.com",
  projectId: "rock-bottom-pos",
  storageBucket: "rock-bottom-pos.appspot.com",
};

const app = initializeApp(firebaseConfig);
const firestore = getFirestore(app);

class SimplifiedFirestore {
  // Real-time Listeners
  subscribeToMenu(callback: (items: MenuItem[]) => void) {
    return onSnapshot(query(collection(firestore, 'menu_items'), orderBy('category')), (snap) => {
      callback(snap.docs.map(d => d.data() as MenuItem));
    });
  }

  subscribeToTables(callback: (tables: Table[]) => void) {
    return onSnapshot(collection(firestore, 'tables'), (snap) => {
      const tables = snap.docs.map(d => ({ id: d.id, ...d.data() } as Table));
      callback(tables.sort((a, b) => a.name.localeCompare(b.name)));
    });
  }

  subscribeToOrders(callback: (orders: Order[]) => void) {
    return onSnapshot(query(collection(firestore, 'orders'), orderBy('createdAt', 'desc')), (snap) => {
      callback(snap.docs.map(d => d.data() as Order));
    });
  }

  // Operations
  async deleteMenuItem(id: string) {
    await deleteDoc(doc(firestore, 'menu_items', id));
  }

  async updateMenu(items: MenuItem[]) {
    const batch = writeBatch(firestore);
    // 1. Clear current menu items (Bulk Overwrite)
    const existing = await getDocs(collection(firestore, 'menu_items'));
    existing.forEach(d => batch.delete(d.ref));

    // 2. Add new items
    items.forEach(item => {
      const ref = doc(firestore, 'menu_items', item.id);
      batch.set(ref, item);
    });
    await batch.commit();
  }

  async createOrder(order: Order) {
    await setDoc(doc(firestore, 'orders', order.id), { ...order, createdAt: Date.now() });
  }

  async updateTable(id: string, updates: Partial<Table>) {
    await setDoc(doc(firestore, 'tables', id), updates, { merge: true });
  }

  async getProfile(): Promise<BusinessProfile> {
    const snap = await getDoc(doc(firestore, 'profile', 'settings'));
    return snap.exists() ? (snap.data() as BusinessProfile) : INITIAL_PROFILE;
  }

  async updateProfile(p: BusinessProfile) {
    await setDoc(doc(firestore, 'profile', 'settings'), p);
  }

  async testConnection() {
    try {
      await getDocs(collection(firestore, 'tables'));
      return true;
    } catch {
      return false;
    }
  }
}

