interface MenuMgmtProps {
  menu: MenuItem[];
  onUpdate: (menu: MenuItem[]) => void;
}

const MenuMgmt: React.FC<MenuMgmtProps> = ({ menu = [], onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return (menu || []).filter(item => 
      item.name.toLowerCase().includes(term) || item.category.toLowerCase().includes(term)
    );
  }, [menu, searchTerm]);

  const handleDelete = async (id: string) => {
    const item = menu.find(i => i.id === id);
    if (!item) return;

    if (window.confirm(`Delete "${item.name}" from Firestore?`)) {
      setIsSyncing(true);
      try {
        await db.deleteMenuItem(id);
        // Local state will be updated via the App.tsx listener
      } catch (err) {
        alert("Failed to delete item from cloud.");
      } finally {
        setIsSyncing(false);
      }
    }
  };

  const handleBulkUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!window.confirm("BULK IMPORT WILL OVERWRITE ALL FIRESTORE MENU ITEMS. Proceed?")) {
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsSyncing(true);
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const text = e.target?.result as string;
        const rows = text.split('\n').filter(r => r.trim()).map(r => r.split(','));

        const newItems: MenuItem[] = [];
        for (let i = 1; i < rows.length; i++) {
          const [name, cat, price, type] = rows[i].map(c => c.replace(/"/g, '').trim());
          if (name && price) {
            newItems.push({
              id: `item_${Date.now()}_${i}`,
              name,
              category: cat.toUpperCase() || 'GENERAL',
              price: parseFloat(price) || 0,
              foodType: type?.toLowerCase().includes('non') ? 'non-veg' : 'veg'
            });
          }
        }

        if (newItems.length > 0) {
          await db.updateMenu(newItems);
          alert(`Successfully uploaded ${newItems.length} items to cloud.`);
        }
      } catch (err) {
        alert("Error parsing CSV.");
      } finally {
        setIsSyncing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

